  {"id":7,"scheme_code":"JK-SCH-0007","name":"Domestic Violence Scheme","short_name":null,"slug":"domestic-violence-scheme","description":null,"scheme_level":"National","state_id":null,"theme_id":26,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"1. Victims of domestic violence, which includes physical, emotional, or psychological abuse by a family member or intimate partner.n2. The victim must be a resident of India.n3. The case should ideally be reported to the police or a legal authority, although immediate assistance can also be provided based on the situation","eligibility_summary":"1. Proof of identity (e.g., Aadhaar card, passport).n2. Proof of residence.n3. Medical reports (if applicable).n4. Police complaint or FIR copy (if available).n5. Any additional documentation supporting the claim of abuse (e.g., photographs of injuries, witness statements)","benefit_type":"Cash Benefit","benefit_description":"1. Immediate financial assistance or relief to cover urgent needs.n2. Access to shelter and temporary accommodation.n3. Legal aid and counseling services.n4. Medical support and access to healthcare facilities.n5. Assistance with filing complaints and navigating the legal system","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"1. Contact the nearest Women’s Helpline or Domestic Violence Cell in the local police station.n2. Visit a local NGO or legal aid center that specializes in domestic violence issues.n3. Submit the required documents and provide a statement detailing the abuse and the need for assistance","portal_url":null,"helpline_number":null,"source_url":"https://wcdhry.gov.in/domestic-violence-scheme/","source_website":"wcdhry.gov.in","is_active":true,"applicable_states":[]},
