  {"id":19,"scheme_code":"JK-SCH-0019","name":"Pradhan Mantri Shram Yogi Maan-Dhan Yojana (PM-SYM) (Old Age Protection)","short_name":"PM-SYM","slug":"pradhan-mantri-shram-yogi-maan-dhan-yojana-pm-sym-old-age-protection","description":null,"scheme_level":"National","state_id":null,"theme_id":18,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian CitizennUnorganised Workers (working as street vendors, agriculture related work, construction site workers, workers in industries of leather, handloom, mid-day meal, rickshaw or auto wheelers, rag picking, carpenters, fisherman’s etc.nAge group of 18-40 yearsnMonthly income is below Rs.15000 and not a member of EPFO/ESIC/NPS (Govt. funded)","eligibility_summary":"Aadhaar cardnSavings bank account or Jan Dhan account details (with IFSC)nMobile phone numbernFirst month's contribution amount","benefit_type":"Pension","benefit_description":"The scheme provides a minimum pension of ₹3,000 per month after age 60, with the Central Government contributing an equal amount to your monthly contribution","benefit_amount":3000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit your nearest Common Service Centre (CSC).nProvide your Aadhaar and bank account details.nComplete self-certification of eligibility.nPay the first month's contribution.nSign the auto-debit mandate form for future monthly contributions.nReceive your pension account details/registration confirmation","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
