  {"id":28,"scheme_code":"JK-SCH-0028","name":"Health Insurance Scheme for Weavers (HIS)","short_name":"HIS","slug":"health-insurance-scheme-for-weavers-his","description":null,"scheme_level":"National","state_id":null,"theme_id":23,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian CitizennThe weaver should be earning at least 50% of his income from handloom weavingnAll weavers, whether male or female, are eligible to be covered under the “Health Insurance Scheme”","eligibility_summary":"Aadhaar cardnWeaver ID / certificate (if available)nBank account detailsnMobile numbernFamily details (for dependent coverage)","benefit_type":"Insurance Cover","benefit_description":"The beneficiaries would avail a package of Rs 15,000 that includes both pre-existing diseases and new diseases. The division in terms of disbursement of the amount according to the medical conditions stands as- Maternity benefits (per child for the first two)- Rs 2500, Eye treatment – Rs 75, Spectacles – Rs 250, Domiciliary Hospitalisation- Rs 4000, Ayurvedic/Unnani/Homeopathic/Siddha- Rs 4000, Hospitalization (including pre and post)- Rs 15000, Baby coverage-500, OPD and limit per illness- Rs 7500","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Offline","application_process":"Visit your nearest Common Service Centre (CSC / Jan Seva Kendra)nProvide:nAadhaar cardnBank account detailsnWeaver identity proof (if available)nComplete e-KYC verificationnApply through the State Handloom Department / Weaver Card SystemnRegister as a certified handloom weavernGet included in the official weaver welfare database","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":29,"scheme_code":"JK-SCH-0029","name":"Pradhan Mantri Kisan Mandhan Yojana","short_name":null,"slug":"pradhan-mantri-kisan-mandhan-yojana","description":null,"scheme_level":"National","state_id":null,"theme_id":18,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian CitizennFor Small and Marginal FarmersnEntry Age between 18 to 40 yearsnCultivable land up to 2 hectares as per land records of the concerned State/UT","eligibility_summary":"Aadhaar cardnBank passbook detailsnLandholding documents (Khatauni / land record)","benefit_type":"Pension","benefit_description":"Assured pension of Rs. 3000/- monthnVoluntary and Contributory Pension SchemenMatching Contribution by the Government of India","benefit_amount":3000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit your nearest Common Service Centre (CSC / Jan Seva Kendra)nProvide:nAadhaar cardnBank passbook detailsnLandholding documents (Khatauni / land record)nCSC operator completes online registration and e-KYCnChoose auto-debit for monthly contribution from bank account","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":30,"scheme_code":"JK-SCH-0030","name":"Self Employment Scheme for Rehabilitation of Manual Scavengers","short_name":null,"slug":"self-employment-scheme-for-rehabilitation-of-manual-scavengers","description":null,"scheme_level":"National","state_id":null,"theme_id":23,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian CitizennIdentified manual scavengers, one from each family, (as defined in para 2.3.1) would be eligible for One Time Cash Assistance (OTCA) of Rs. 40,000/- or any such amount as OTCA as revised from time to time","eligibility_summary":"Aadhaar Card (identity proof)nProof of Address (Ration Card / Voter ID / Electricity bill, etc.)nAge Proof (Birth certificate / School certificate / other valid document)nManual Scavenger Identification Certificate issued by:nState Government / Urban Local Body / Gram PanchayatnBank Account Details (copy of passbook with IFSC code)nPassport-size photographsnCaste Certificate (if applicable, as per state requirements)nMobile number linked for communication and verification","benefit_type":"Scholarship / Fee Support","benefit_description":"The manual scavenger and the dependents (as defined in para 2.3.2) shall be provided, free of cost, skill training of their choice from the list of such trainings organized by the National Safai Karmacharis Finance and Development Corporation (NSKFDC) from time to time . A monthly stipend of Rs. 3000/-(Rupees three thousand only) or any such amount as may be decided from time to time to shall be remitted by NSKFDC","benefit_amount":3000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"You generally cannot apply directly like a normal scheme. The process is:nnIdentification through government survey / local authority listnRegistration via State Urban Local Bodies or Gram PanchayatnAssistance through NSKFDC (National Safai Karamcharis Finance & Development Corporation)nThen selection for:ncash assistancentrainingnloan/self-employment support","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":31,"scheme_code":"JK-SCH-0031","name":"National Safai Karamcharis Finance and Development Corporation (NSKFDC)","short_name":"NSKFDC","slug":"national-safai-karamcharis-finance-and-development-corporation-nskfdc","description":null,"scheme_level":"National","state_id":null,"theme_id":23,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian CitizennPeople involved as Safai karmacharis and manual scavengers","eligibility_summary":"Scheme provides financial assistance to the Safai Karamcharis, Manual Scavengers and their dependants through SCAs/RRBs/Nationalized Banks for any viable income generating schemes including sanitation related activities and for education in India and Abroad","benefit_type":"Scholarship / Fee Support","benefit_description":"NSKFDC gives low-interest loans through banks/State agencies for income activities such as:nnSmall business / shop / vendingnSanitation-related machinery or servicesnE-rickshaw / green businessnAny viable self-employment activity/\"Skill development training programsnStipend during training (as per scheme rules)nAwareness camps and job fairsnSupport for rehabilitation activities","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Does not give money directly in most casesnWorks through:nState Channelising Agencies (SCAs)nRegional Rural Banks (RRBs)nNationalised banks","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":32,"scheme_code":"JK-SCH-0032","name":"MGNREGA","short_name":null,"slug":"mgnrega","description":null,"scheme_level":"National","state_id":null,"theme_id":10,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian CitizennAny person who is above the age of 18 and resides in rural areas is entitled to apply for work","eligibility_summary":"MGNREGA Job CardnIssued by the Gram PanchayatnContains family details and work historynUsed to apply for work and receive wages","benefit_type":"In-kind / Material","benefit_description":"Any applicant is entitled to work within 15 days, for as many as he/she has applied, subject to a limit of 100 days per household per year.nWage rate (220) has been increased and to be incorporated","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit your Gram Panchayat officenSubmit application for a Job CardnProvide basic documents:nAadhaar cardnAddress proofnPassport-size photonAfter verification, Job Card is issued (usually free of cost)nThen you can directly demand work anytime","portal_url":null,"helpline_number":null,"source_url":"https://eshram.gov.in/employment-schemes","source_website":"eshram.gov.in","is_active":true,"applicable_states":[]},
  {"id":33,"scheme_code":"JK-SCH-0033","name":"Deen Dayal Upadhyay – Gramin Kaushalya Yojana (DDU-GKY)","short_name":"DDU-GKY","slug":"deen-dayal-upadhyay-gramin-kaushalya-yojana-ddu-gky","description":null,"scheme_level":"National","state_id":null,"theme_id":6,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian CitizennBetween the ages of 15 and 35 years, are eligible for the training programs.nFor women and other vulnerable groups like persons with disabilities, the upper age limit is relaxed to 45 years","eligibility_summary":"Identity & Age ProofnnAadhaar Card or other government photo IDnBirth Certificate or proof of date of birthnnEligibility/Household Documents (any applicable document)nnBPL CardnMGNREGA Job Card (where eligible)nRSBY CardnAntyodaya Anna Yojana (AAY) CardnBPL PDS CardnNRLM Self-Help Group membership proofnnCategory Certificates (if applicable)nnSC/ST CertificatenDisability Certificate (PwD candidates)nOther category-related certificates as required by the state authority","benefit_type":"Training","benefit_description":"Deen Dayal Upadhyaya Grameen Kaushalya Yojana (DDU-GKY) aims to skill rural youth who are poor and provide them with jobs having regular monthly wages or above the minimum wages","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official DDU-GKY/Kaushal Panjee portal:nKaushal Panjee Registration PortalnSelect Candidate Registration.nChoose New Registration.nFill in your personal, educational, and contact details.nUpload the required documents.nSubmit the application and save the registration/reference number","portal_url":null,"helpline_number":null,"source_url":"https://eshram.gov.in/employment-schemes","source_website":"eshram.gov.in","is_active":true,"applicable_states":[]},
  {"id":34,"scheme_code":"JK-SCH-0034","name":"Deen Dayal Updhyaya Antyodaya Yojana (Day)","short_name":null,"slug":"deen-dayal-updhyaya-antyodaya-yojana-day","description":null,"scheme_level":"National","state_id":null,"theme_id":34,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Rural and Urban Poor Households","eligibility_summary":"Aadhaar CardnIdentity proofnAddress proofnBank account detailsnPassport-size photographsnIncome/BPL certificate (where applicable)nSHG-related documents (for group-based benefits)","benefit_type":"Credit / Subsidy","benefit_description":"Organizing poor women into Self-Help Groups (SHGs).nProviding access to bank loans and financial services.nSkill development and livelihood promotion.nSupport for entrepreneurship and income-generating activities.nSpecial focus on vulnerable groups and women's economic empowerment./\"Urban poor obtain skill training and wage employment.nIndividuals and groups start micro-enterprises through bank-linked loans.nUrban homeless access shelters and support services.nStreet vendors access credit, social security, and livelihood support","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Contact your Gram Panchayat, Block Development Office, or local Self-Help Group federation./Apply through your local Urban Local Body (Municipality/Municipal Corporation)","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":35,"scheme_code":"JK-SCH-0035","name":"PM SVANidhi","short_name":null,"slug":"pm-svanidhi","description":null,"scheme_level":"National","state_id":null,"theme_id":9,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian CitizennStreet vendors in possession of Certificate of Vending / Identity Card issued by Urban Local Bodies (ULBs);nThe vendors, who have been identified in the survey but have not been issued Certificate of Vending / Identity Card","eligibility_summary":"Aadhaar CardnMobile number linked to AadhaarnVoter ID/other ID proof (if required)nCertificate of Vending (CoV), Identity Card, or Letter of Recommendation (LoR)nBank account details/passbooknPassport-size photograph (if requested by the lending institution)","benefit_type":"Credit / Subsidy","benefit_description":"To facilitate working capital loan up to 10,000.nTo incentivize regular repayment.nTo reward digital transactions","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain or verify your CoV/ID Card/LoR through your municipality or Town Vending Committee.nApply through a participating bank, microfinance institution, or Common Service Centre (CSC).nSubmit the required documents and complete e-KYC.nAfter approval, the loan is credited directly to your bank account","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":36,"scheme_code":"JK-SCH-0036","name":"Pradhan Mantri Kaushal Vikas Yojana (PMKVY)","short_name":"PMKVY","slug":"pradhan-mantri-kaushal-vikas-yojana-pmkvy","description":null,"scheme_level":"National","state_id":null,"theme_id":6,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian Citizenn12th class dropouts or 10th pass students can enroll in PMKVY to develop their skill set.nApplicable for any candidate of Indian nationality who is of age between 18-45 years","eligibility_summary":"Aadhaar CardnPassport-size photographnProof of Date of Birth (10th certificate, birth certificate, etc.)nEducational qualification certificates/marksheetsnMobile numbernCaste certificate (if applicable)","benefit_type":"Training","benefit_description":"Free skill trainingnGovernment-recognized certificationnTraining in sectors such as IT, electronics, healthcare, retail, construction, AI, cybersecurity, drones, and more.nCareer guidance and industry-relevant skills","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Online","application_process":"Register on the official Skill India platform:nSkill India Digital PortalnCreate your profile using Aadhaar and mobile number.nSearch for PMKVY training courses near you or online.nSelect a training center and course.nUpload required documents and complete enrollment.nAttend training and appear for assessment/certification","portal_url":null,"helpline_number":null,"source_url":"https://eshram.gov.in/employment-schemes","source_website":"eshram.gov.in","is_active":true,"applicable_states":[]},
  {"id":37,"scheme_code":"JK-SCH-0037","name":"Prime Minister Employment Generation Programme (PMEGP)","short_name":"PMEGP","slug":"prime-minister-employment-generation-programme-pmegp","description":null,"scheme_level":"National","state_id":null,"theme_id":9,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Should be an Indian CitizennAny individual, above 18 years of age.nAt least VIII standard pass for projects costing above Rs.10 lakh in the manufacturing sector and above Rs. 5 lakh in the business / service sector","eligibility_summary":"Aadhaar CardnPAN CardnPassport-size photographnProject Report/Business PlannEducational qualification certificate (if applicable)nCaste/Category certificate (if applicable)nRural area certificate (if applicable)nSkill development or EDP training certificate (if available)nBank account details","benefit_type":"Credit / Subsidy","benefit_description":"PMEGP (Prime Minister Employment Generation Programme) helps individuals start a new business or micro-enterprise by providing a bank loan with a government subsidy of up to 35% of the project cost. It supports self-employment, entrepreneurship, and job creation in both rural and urban areas","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Apply through the official PMEGP portal:nPMEGP e-PortalnSelect Individual Application.nComplete Aadhaar verification.nFill in personal, project, and bank details.nUpload required documents.nSubmit the application.nAfter scrutiny by KVIC/KVIB/DIC and the bank, the loan proposal is processed","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":38,"scheme_code":"JK-SCH-0038","name":"Indira Gandhi National Old Age Pension Scheme (IGNOAPS)","short_name":"IGNOAPS","slug":"indira-gandhi-national-old-age-pension-scheme-ignoaps","description":null,"scheme_level":"National","state_id":null,"theme_id":18,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"The applicant should be a citizen of India.nThe applicant should be living Below Poverty Line.nThe applicant should be at least 60 years of age","eligibility_summary":"Aadhaar CardnAge proof (Birth Certificate, Voter ID, School Certificate, etc.)nBPL Card / BPL CertificatenIncome Certificate (if required by the state)nResidence ProofnBank Passbook (account linked with Aadhaar)nPassport-size photographsnMobile number (for communication)","benefit_type":"Pension","benefit_description":"A monthly pension of ₹ 200 up to 79 years and ₹ 500 thereafter","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Both","application_process":"One can download UMANG App or visit website https://web.umang.gov.in/web_new/homenThe citizen can login using mobile number and OTP.nOnce logged In, citizen can search for NSAP.nClick on “Apply Online”nFill the basic details, choose the mode of payment of pension, upload photo and click on “Submit”","portal_url":"https://web.umang.gov.in/web_new/home","helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":39,"scheme_code":"JK-SCH-0039","name":"Indira Gandhi National Widow Pension Scheme (IGNWPS)","short_name":"IGNWPS","slug":"indira-gandhi-national-widow-pension-scheme-ignwps","description":null,"scheme_level":"National","state_id":null,"theme_id":25,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"The applicant must be a widow in the age group of 40-79 years.nThe applicant should belong to a household living below the poverty line according to the criteria prescribed by the Govt. of India","eligibility_summary":"Death Certificate of husband – With the name of the surviving wife(widow).nBPL Card.nAge Proof - For age, the birth certificate or school certificate may be relied on. In their absence ration card and EPIC may be considered. If there is no valid document, any Medical Officer of any government hospital may be authorized to issue the age certificate","benefit_type":"Pension","benefit_description":"A pension of Rs.300/- per month is provided to Widows between 40 years and 79 years. For persons who are 80 years and above the pension is Rs.500/- per month","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Both","application_process":"One can download UMANG App or visit website https://web.umang.gov.in/web_new/homenThe citizen can login using mobile number and OTP.nOnce logged In, citizen can search for NSAP.nClick on “Apply Online”nFill the basic details, choose the mode of payment of pension, upload photo and click on “Submit”","portal_url":"https://web.umang.gov.in/web_new/home","helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":40,"scheme_code":"JK-SCH-0040","name":"ABHA","short_name":null,"slug":"abha","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Indian Citizen","eligibility_summary":"Adhaar card and active phone number linked with Adhaar","benefit_type":"Insurance Cover","benefit_description":"Establish unique identity across different healthcare providers within the healthcare ecosystem/Link all healthcare benefits ranging from public health programmes to insurance schemes to your unique ABHA number/Avoid long lines for registration in healthcare facilities across the country/Seamless sign up for PHR (Personal Health Records) applications such as ABDM application for health data sharing","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official ABHA portal:nABHA Registration PortalnSelect \"Create ABHA Number\".nChoose Aadhaar or Driving Licence.nVerify using OTP.nCreate your ABHA address (for example: yourname@abdm).nDownload or save your ABHA card","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":41,"scheme_code":"JK-SCH-0041","name":"JSY (Janani Suraksha Yojana)","short_name":null,"slug":"jsy-janani-suraksha-yojana","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Pregnant women from BPL (Below Poverty Line) families.nSC/ST women.nDelivery should take place in a government or accredited private health facility to receive institutional delivery benefits.nIn some states/categories, age and parity conditions may appl","eligibility_summary":"Aadhaar CardnMother and Child Protection (MCP) CardnBPL Card (if applicable)nSC/ST Certificate (if applicable)nBank Account PassbooknJSY Card / Registration details from the health facilitynMobile NumbernResidence Proof (if required locally)","benefit_type":"Cash Benefit","benefit_description":"The assistance amount depends on the state and whether the area is rural or urban. Common benefits include:nnCash assistance for institutional delivery.nSupport through ASHA workers.nAssistance for eligible home deliveries in certain cases","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Register your pregnancy at the nearest:nSub-CentrenPrimary Health Centre (PHC)nCommunity Health Centre (CHC)nGovernment HospitalnObtain an MCP Card and JSY registration.nAttend antenatal check-ups.nDeliver at a government or accredited private facility.nSubmit bank account and Aadhaar details for Direct Benefit Transfer (DBT).nThe incentive amount is credited directly to the beneficiary's bank account after verification","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":42,"scheme_code":"JK-SCH-0042","name":"NFSA (National Food Security Act, 2013)","short_name":null,"slug":"nfsa-national-food-security-act-2013","description":null,"scheme_level":"National","state_id":null,"theme_id":14,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Priority Household (PHH) or Antyodaya Anna Yojana (AAY) households","eligibility_summary":"Aadhaar Card of family membersnProof of residencenIdentity proofnMobile numbernPassport-size photographsnExisting ration card surrender certificate (if transferring from another state/district)nIncome or eligibility-related documents, where applicable","benefit_type":"In-kind / Material","benefit_description":"Highly subsidized food grains through ration shops.nPHH beneficiaries: 5 kg food grains per person per month.nAAY households: 35 kg food grains per household per month","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official NFSA portal:nNFSA Apply for Ration CardnSelect your State/UT Food Department portal.nRegister/login on the state portal.nFill in family details and address details.nUpload required documents.nSubmit the application and note the acknowledgment/reference number.nTrack the application status on the state portal","portal_url":null,"helpline_number":null,"source_url":"https://nfsa.gov.in","source_website":"nfsa.gov.in","is_active":true,"applicable_states":[]},
  {"id":43,"scheme_code":"JK-SCH-0043","name":"UDID (Unique Disability ID) Card","short_name":null,"slug":"udid-unique-disability-id-card","description":null,"scheme_level":"National","state_id":null,"theme_id":20,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Any person with a disability who wishes to obtain:nnA disability certificate, ornA UDID card linked to an existing disability certificate","eligibility_summary":"Aadhaar Card (or other identity proof)nPassport-size photographnAddress proofnDisability-related medical documents/reportsnMobile numbernExisting disability certificate (if already issued)","benefit_type":"Pension","benefit_description":"Single national disability identity card.nEasier access to disability-related schemes and benefits.nOnline verification of disability certificates.nReduces the need to carry multiple documents.nFacilitates access to pensions, scholarships, assistive devices, travel concessions, and other government programs","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official UDID portal:nUDID Portal Registration PagenClick \"Apply for Disability Certificate & UDID Card\".nCreate an account and fill in the application form.nUpload the required documents.nSubmit the application.nTrack the application status online.nAttend medical assessment if required by the designated medical authority.nOnce approved, the disability certificate and UDID card are issued digitally","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":44,"scheme_code":"JK-SCH-0044","name":"Pradhan Mantri Ujjwala Yojana (PMUY)","short_name":"PMUY","slug":"pradhan-mantri-ujjwala-yojana-pmuy","description":null,"scheme_level":"National","state_id":null,"theme_id":16,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"A woman of the household.nnAt least 18 years old.nnBelonging to an eligible poor household (as identified under government criteria).nnNot already having an LPG connection in the same household","eligibility_summary":"Aadhaar CardnnRation Card / Family composition documentnnBank account details / passbooknnAddress proofnnPassport-size photographnnMobile number","benefit_type":"Cash Benefit","benefit_description":"Free LPG connection for eligible women.nFinancial assistance for LPG connection setup.nReduced indoor air pollution and smoke exposure.nImproved health outcomes for women and children.nCleaner and safer cooking fuel.nTime saved from collecting traditional fuels.nEnhanced convenience in cooking.nWomen's empowerment through ownership of the LPG connection.nReduced dependence on firewood, coal, and biomass fuels.nEnvironmental benefits through cleaner energy use.nAccess to subsidized LPG refills as per government policy","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest LPG distributor (Indane, Bharat Gas, or HP Gas).nnAsk for the PMUY application form.nnFill in the details and attach the required documents.nnSubmit the application.nnAfter verification, an LPG connection is sanctioned.nnThe beneficiary receives the connection and related support as per the scheme rules","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":45,"scheme_code":"JK-SCH-0045","name":"Sukanya Samriddhi Yojana (SSY)","short_name":"SSY","slug":"sukanya-samriddhi-yojana-ssy","description":null,"scheme_level":"National","state_id":null,"theme_id":27,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"The account can be opened in the name of a girl child below 10 years of age.nThe account may be opened by a parent or legal guardian.nA maximum of two girl children per family are generally eligible (exceptions apply for twins/triplets)","eligibility_summary":"Birth Certificate of the girl childnAadhaar Card (where applicable)nIdentity proof of parent/guardiannAddress proof of parent/guardiannPassport-size photographs (if required by the bank/post office)","benefit_type":"Credit / Subsidy","benefit_description":"Government-backed savings scheme.nAttractive interest rate notified by the Government from time to time.nTax benefits under applicable provisions of the Income Tax Act.nDeposits can be made until the account completes 15 years from opening.nThe account matures 21 years from the date of opening or upon eligible closure conditions","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit a:nIndia Post post office, ornAuthorized bank branch offering SSY accounts.nObtain and fill out the SSY account opening form.nSubmit the required documents.nMake the initial deposit (minimum amount as per current scheme rules).nThe account will be opened, and a passbook will be issued","portal_url":null,"helpline_number":null,"source_url":"https://www.nsiindia.gov.in","source_website":"www.nsiindia.gov.in","is_active":true,"applicable_states":[]},
  {"id":46,"scheme_code":"JK-SCH-0046","name":"Swadhar Greh - A Scheme for women in difficult circumstances","short_name":null,"slug":"swadhar-greh-a-scheme-for-women-in-difficult-circumstances","description":null,"scheme_level":"National","state_id":null,"theme_id":26,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Homeless and shelter less BPL","eligibility_summary":"Deserted women without social or economic supportnVictims of domestic violence or family disputesnWomen rendered homeless due to natural disastersnWomen released from prison without family supportnTrafficked women rescued from exploitationnWomen affected by HIV/AIDS who lack social and economic supportnOther women in distress who need institutional support and rehabilitation","benefit_type":"Training","benefit_description":"Safe shelter/accommodationnFood and clothingnMedical care and health servicesnPsychological counselingnLegal aid and guidancenVocational training and skill developmentnEconomic and social rehabilitation support","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Approach the nearest:nDistrict Women & Child Development OfficenDistrict Social Welfare OfficenOne Stop Centre (OSC)nPolice Station (for referral in emergency cases)nSwadhar Greh Home directlynSubmit the application/referral along with available documents.nThe authorities verify the case and assess eligibility.nIf approved, the woman is admitted to a Swadhar Greh and provided support services and rehabilitation assistance","portal_url":null,"helpline_number":null,"source_url":"https://transformingindia.mygov.in","source_website":"transformingindia.mygov.in","is_active":true,"applicable_states":[]},
