  {"id":48,"scheme_code":"JK-SCH-0048","name":"Rashtriya Krishi Vikas Yojana – Remunerative Approaches for Agriculture and Allied Sector Rejuvenation (RKVY-RAFTAAR)","short_name":"RKVY-RAFTAAR","slug":"rashtriya-krishi-vikas-yojana-remunerative-approaches-for-agriculture-and-allied-sector-rejuvenation-rkvy-raftaar","description":null,"scheme_level":"National","state_id":null,"theme_id":12,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"FarmersnFarmer Producer Organizations (FPOs)nSelf-Help Groups (SHGs)nAgri-entrepreneurs and startupsnAgricultural institutions and universitiesnState government agencies implementing agricultural projects","eligibility_summary":"Aadhaar CardnIdentity ProofnAddress ProofnBank Account DetailsnLand ownership/lease documents (for farmer components)nProject proposal (for startup or infrastructure projects)nMobile numbernPassport-size photograph","benefit_type":"Training","benefit_description":"Agricultural infrastructure developmentnFarm machinery supportnCapacity building and trainingnIrrigation and watershed developmentnPost-harvest management facilitiesnStartup incubation, mentoring, and funding support for agri-innovations","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Contact the nearest Agriculture Department office.nMeet the Agriculture Development Officer (ADO) or District Agriculture Officer.nSubmit an application with required documents.nThe proposal is evaluated and approved based on local priorities and fund availability./\"Apply through an approved RKVY-RAFTAAR Agri-Business Incubator (R-ABI).nSubmit an innovation/business proposal.nParticipate in screening, mentoring, and incubation.nEligible startups may receive incubation support and funding assistance","portal_url":null,"helpline_number":null,"source_url":"https://rkvy.da.gov.in","source_website":"rkvy.da.gov.in","is_active":true,"applicable_states":[]},
  {"id":49,"scheme_code":"JK-SCH-0049","name":"Pradhan Mantri Fasal Bima Yojana (PMFBY)","short_name":"PMFBY","slug":"pradhan-mantri-fasal-bima-yojana-pmfby","description":null,"scheme_level":"National","state_id":null,"theme_id":12,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Farmers growing notified crops in notified areas.nnSharecroppers and tenant farmers may also be eligible as per state guidelines","eligibility_summary":"Aadhaar CardnIdentity ProofnBank Account PassbooknLand ownership records or cultivation proofnSowing/Crop detailsnMobile NumbernPassport-size photograph","benefit_type":"Insurance Cover","benefit_description":"Insurance coverage for notified crops.nFinancial assistance in case of crop loss due to drought, flood, cyclone, hailstorm, pest attack, disease, and other covered risks.nStabilizes farmers' income and encourages continued farming","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the PMFBY portal:nPMFBY Farmer RegistrationnRegister as a farmer.nEnter land and crop details.nUpload the required documents.nPay the applicable premium.nSubmit the application and save the acknowledgment number","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":50,"scheme_code":"JK-SCH-0050","name":"National Food Security Mission (NFSM)","short_name":"NFSM","slug":"national-food-security-mission-nfsm","description":null,"scheme_level":"National","state_id":null,"theme_id":12,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Farmers cultivating notified crops under NFSM.nSmall and marginal farmers are given priority.nWomen farmers and SC/ST farmers receive earmarked allocations under the scheme guidelines.nAssistance is generally available up to a specified area limit per season","eligibility_summary":"Aadhaar CardnIdentity ProofnAddress ProofnBank Account DetailsnLand Ownership Records / Cultivation ProofnPassport-size PhotographnMobile NumbernCrop Details and Area under Cultivation","benefit_type":"Training","benefit_description":"Distribution of certified and quality seeds.nCluster demonstrations and technology demonstrations.nFarm machinery and agricultural implements.nMicronutrients and soil amendments.nPlant protection measures.nTraining and capacity building programs","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Agriculture Department office.nContact the Agriculture Development Officer (ADO), Agriculture Extension Officer, or Block Agriculture Officer.nSubmit the application along with the required documents.nAfter verification, assistance is provided under the relevant NFSM component","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":51,"scheme_code":"JK-SCH-0051","name":"Soil Health Card Scheme (SHC)","short_name":"SHC","slug":"soil-health-card-scheme-shc","description":null,"scheme_level":"National","state_id":null,"theme_id":12,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"All farmers, including small, marginal, and large farmers.nIndividual landowners and cultivators can avail of soil testing services","eligibility_summary":"Aadhaar CardnIdentity ProofnLand ownership records or cultivation proofnMobile NumbernBank details (if required by the state)","benefit_type":null,"benefit_description":"Free or subsidized soil testing.nPersonalized fertilizer recommendations.nInformation on soil amendments such as lime, gypsum, and organic manure.nBetter crop yields and reduced input costs.nLong-term improvement in soil health","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Agriculture Department office, Krishi Vigyan Kendra (KVK), or Soil Testing Laboratory.nSubmit a request for soil testing.nSoil samples are collected from the farm or brought by the farmer as per guidelines.nThe sample is tested in an authorized laboratory.nThe Soil Health Card is generated and issued to the farmer","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":52,"scheme_code":"JK-SCH-0052","name":"Pradhan Mantri Krishi Sinchayee Yojana (PMKSY)","short_name":"PMKSY","slug":"pradhan-mantri-krishi-sinchayee-yojana-pmksy","description":null,"scheme_level":"National","state_id":null,"theme_id":13,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Individual farmers.nFarmer groups and Farmer Producer Organizations (FPOs).nFarmers owning or cultivating agricultural land.nEligibility and subsidy rates may vary by state and component","eligibility_summary":"Aadhaar CardnIdentity ProofnAddress ProofnLand Ownership Records / Land Lease DocumentsnBank Account DetailsnPassport-size PhotographnMobile NumbernDetails of proposed irrigation system/project","benefit_type":null,"benefit_description":"Har Khet Ko Pani (HKKP) – Bringing irrigation water to every farm.nPer Drop More Crop (PDMC) – Promoting efficient irrigation systems.nWatershed Development – Soil and water conservation in rainfed areas.nAccelerated Irrigation Benefit Programme (AIBP) – Completion of major and medium irrigation projects","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Agriculture Department office.nContact the Agriculture Officer or Block Agriculture Officer.nSubmit the application with the required documents.nAfter verification, assistance/subsidy is sanctioned under the relevant PMKSY component","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":53,"scheme_code":"JK-SCH-0053","name":"National Means-cum-Merit Scholarship Scheme (NMMS / NMMSS)","short_name":"NMMS / NMMSS","slug":"national-means-cum-merit-scholarship-scheme-nmms-nmmss","description":null,"scheme_level":"National","state_id":null,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"A student must:nnBe studying in Class VIII in a Government, Government-aided, or Local Body school.nHave parental income from all sources not exceeding ₹3.5 lakh per year.nQualify the State-Level NMMS Examination (MAT and SAT).nHave secured the minimum marks prescribed by the State/UT in the qualifying examination (usually Class VII)","eligibility_summary":"Class VII mark sheetnIncome Certificate of parents/guardiannAadhaar CardnBank Account detailsnCaste Certificate (if applicable)nDisability Certificate (if applicable)nDomicile Certificate (as required by the State)nPassport-size photograph","benefit_type":"Scholarship / Fee Support","benefit_description":"₹12,000 per year (₹1,000 per month) for selected students.nThe scholarship is awarded from Class IX and can be renewed up to Class XII, subject to eligibility and academic performance","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Offline","application_process":"Apply through your school when the State Education Department announces NMMS applications.nAppear for the State-level NMMS examination","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":54,"scheme_code":"JK-SCH-0054","name":"Samagra Shiksha Abhiyan (Samagra Shiksha)","short_name":null,"slug":"samagra-shiksha-abhiyan-samagra-shiksha","description":null,"scheme_level":"National","state_id":null,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Students in Government and Government-aided schools.nTeachers and teacher educators.nSchools requiring infrastructure and academic support.nChildren from disadvantaged and vulnerable groups","eligibility_summary":"Depending on the benefit component:nnSchool admission recordsnAadhaar Card (where required)nCaste Certificate (if applicable)nDisability Certificate (for inclusive education benefits)nIncome-related documents (for certain student support components)","benefit_type":"Training","benefit_description":"Free textbooks and uniforms for eligible students.nConstruction of classrooms, toilets, drinking water facilities, and other school infrastructure.nTeacher recruitment, training, and capacity building.nInclusive education for children with special needs.nICT and digital learning initiatives.nVocational education from secondary classes onwards","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"There is no direct application by students for Samagra Shiksha itself. Benefits are delivered through schools and State Education Departments","portal_url":null,"helpline_number":null,"source_url":"https://samagra.education.gov.in","source_website":"samagra.education.gov.in","is_active":true,"applicable_states":[]},
  {"id":55,"scheme_code":"JK-SCH-0055","name":"National Overseas Scholarship (NOS)","short_name":"NOS","slug":"national-overseas-scholarship-nos","description":null,"scheme_level":"National","state_id":null,"theme_id":5,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Scheduled Castes (SC)nDenotified, Nomadic and Semi-Nomadic Tribes (DNTs)nLandless Agricultural LabourersnTraditional Artisans","eligibility_summary":"Aadhaar CardnCaste Certificate (if applicable)nIncome CertificatenEducational certificates and mark sheetsnAdmission/offer letter from a foreign university (as per scheme requirements)nPassportnPassport-size photographnBank account detailsnOther documents specified in the annual guidelines","benefit_type":"Insurance Cover","benefit_description":"Tuition feesnLiving/maintenance allowancenVisa feesnMedical insurancenAirfare and related travel expensesnOther approved academic expenses","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official NOS portal:nApply for National Overseas ScholarshipnRegister and create an account.nFill in the online application form.nUpload the required documents.nSubmit the application before the notified deadline.nTrack application status and results on the portal","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":56,"scheme_code":"JK-SCH-0056","name":"PM CARES for Children Scheme","short_name":null,"slug":"pm-cares-for-children-scheme","description":null,"scheme_level":"National","state_id":null,"theme_id":28,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Children who:nnLost both parents due to COVID-19.nLost a surviving parent due to COVID-19.nLost a legal guardian/adoptive parent due to COVID-19.nWere below 18 years of age on the date of death of the parent/guardian.nWere identified and registered under the scheme within the prescribed period","eligibility_summary":"Birth CertificatenAadhaar Card (if available)nDeath certificate(s) of parent(s)/guardian indicating COVID-19-related deathnResidence proofnBank account details (where applicable)nSchool recordsnPassport-size photographnAny other documents required by the District Administration","benefit_type":"Insurance Cover","benefit_description":"Corpus fund created for each eligible child.nLump-sum financial support provided when the child reaches 23 years of age.nMonthly stipend from age 18 to 23 years for personal needs./Admission in nearest Government or Kendriya Vidyalaya school.nPayment of school fees, uniforms, books, and educational expenses where applicable.nSupport for higher education through scholarships and educational loans./Coverage under Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana (AB-PMJAY).nHealth insurance cover of ₹5 lakh per year.nPremium paid by PM CARES","benefit_amount":500000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"The scheme is generally administered through the District Administration","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":57,"scheme_code":"JK-SCH-0057","name":"Sponsorship under Mission Vatsalya","short_name":null,"slug":"sponsorship-under-mission-vatsalya","description":null,"scheme_level":"National","state_id":null,"theme_id":28,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Children below 18 years of age who are in difficult circumstances, including:nnOrphaned children.nChildren with a single parent.nChildren whose parents are unable to care for them due to illness, disability, destitution, imprisonment, or other crises.nChildren rescued from child labour, trafficking, abuse, neglect, or exploitation.nChildren living in vulnerable families at risk of abandonment.nChildren affected by natural disasters, conflict, or emergencies","eligibility_summary":"Birth Certificate/Age ProofnAadhaar Card (child and parent/guardian, if available)nResidence ProofnIncome CertificatenBank Account Details of parent/guardiannDeath Certificate of parent(s) (if applicable)nMedical records (if applicable)nSchool certificate/enrollment proofnChild Welfare Committee (CWC) or District Child Protection Unit (DCPU) assessment documents","benefit_type":"Cash Benefit","benefit_description":"Financial assistance of up to ₹4,000 per month per child (subject to state implementation and assessment).nSupport for:nEducation expensesnNutritionnHealthcarenClothing and basic needsnRehabilitation and family strengthening","benefit_amount":4000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Contact the District Child Protection Unit (DCPU)","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":58,"scheme_code":"JK-SCH-0058","name":"Scheme for Care and Support to Victims under Sections 4 & 6 of the POCSO Act, 2012 (Nirbhaya Fund)","short_name":null,"slug":"scheme-for-care-and-support-to-victims-under-sections-4-6-of-the-pocso-act-2012-nirbhaya-fund","description":null,"scheme_level":"National","state_id":null,"theme_id":28,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Minor girl children (below 18 years of age) who are pregnant due to offences under:nnSection 4 – Punishment for penetrative sexual assault.nSection 6 – Punishment for aggravated penetrative sexual assault under the POCSO Act","eligibility_summary":"The scheme guidelines emphasize that benefits should not be denied due to lack of documents, and a copy of the FIR is not mandatory for availing support. The responsibility for ensuring FIR registration lies with the authorities","benefit_type":"Training","benefit_description":"Prenatal and postnatal healthcare.nInstitutional delivery services.nMedical examinations and treatment.nNutrition support during pregnancy and after childbirth./Trauma counseling.nMental health support.nFamily counseling and rehabilitation services./Safe accommodation where required.nPlacement in appropriate child care institutions if necessary./Legal aid and assistance during investigation and trial.nSupport persons to assist the child through the judicial process./Continuation of schooling.nVocational training and skill development where appropriate.nSocial reintegration support./Financial support for care and rehabilitation needs as per approved norms and case assessment","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Report the case to the police, Special Juvenile Police Unit (SJPU), or Childline/child protection authorities.nThe child is produced before the Child Welfare Committee (CWC).nA care plan is prepared by the District Child Protection Unit (DCPU) and relevant authorities.nMedical, legal, educational, and rehabilitation services are arranged.nFinancial and support services are provided through the designated implementing agencies","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":59,"scheme_code":"JK-SCH-0059","name":"Shakti Sadan","short_name":null,"slug":"shakti-sadan","description":null,"scheme_level":"National","state_id":null,"theme_id":26,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Women in difficult circumstances.nVictims/survivors of trafficking.nDestitute and abandoned women.nWidows without support.nWomen affected by violence or abuse.nWomen requiring temporary or long-term shelter and rehabilitation","eligibility_summary":"Aadhaar Card (if available)nIdentity ProofnAddress ProofnPassport-size photographsnMedical reports (if applicable)nPolice report/FIR (for trafficking or violence cases, where applicable)nCourt orders or referral documents (if any)nWidow certificate/death certificate of spouse (for widows, if applicable)nAny referral from:nOne Stop Centre (OSC)nPolice StationnDistrict AdministrationnChild Welfare Committee (where relevant)nNGO or Social Welfare Department","benefit_type":"Training","benefit_description":"Safe accommodation and shelter.nFood and clothing.nMedical care and health services.nPsychological counseling.nLegal aid and support.nEducation and skill development.nVocational training and livelihood assistance.nAssistance in opening bank accounts and accessing social security schemes","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Approach the nearest:nOne Stop Centre (OSC)nWomen Helpline (181)nPolice StationnDistrict Social Welfare OfficenWomen & Child Development DepartmentnA referral is made to the nearest Shakti Sadan.nEligibility and need assessment are conducted.nAdmission is granted and rehabilitation services begin","portal_url":null,"helpline_number":"181","source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":60,"scheme_code":"JK-SCH-0060","name":"National Mental Health Programme (NMHP)","short_name":"NMHP","slug":"national-mental-health-programme-nmhp","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Mental health services are available to all citizens through public health facilities","eligibility_summary":"For availing treatment under NMHP/DMHP, hospitals may typically ask for:nnAadhaar Card or other ID proofnAddress proofnMobile numbernPrevious medical records or prescriptions (if available)nReferral slip (if referred from another facility)nnEmergency counseling and Tele-MANAS services generally do not require extensive documentation","benefit_type":"Service Delivery","benefit_description":"Free or affordable mental health consultations.nCounseling and psychological support.nDiagnosis and treatment of mental illnesses.nMedicines for mental health conditions through public health facilities.nDistrict Mental Health Programme (DMHP) services at district hospitals.nReferral to specialist psychiatric care when needed.nCommunity awareness and mental health promotion activities.n24×7 tele-counseling through Tele-MANAS (14416).nRehabilitation and follow-up support for persons with mental illness.nMental health services integrated with primary healthcare facilities","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest:nPrimary Health Centre (PHC)nCommunity Health Centre (CHC)nDistrict HospitalnMedical College HospitalnAsk for mental health or psychiatry services under the District Mental Health Programme.nUndergo assessment and receive counseling/treatment./Dial 14416 or 1-800-89-14416 from anywhere in India.nReceive free tele-counseling and referral support","portal_url":null,"helpline_number":"14416","source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":61,"scheme_code":"JK-SCH-0061","name":"Janani Shishu Suraksha Karyakram (JSSK)","short_name":"JSSK","slug":"janani-shishu-suraksha-karyakram-jssk","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"All pregnant women delivering in Government health institutions.nSick newborns (up to 30 days after birth).nSick infants (up to 1 year of age) accessing public health facilities","eligibility_summary":"Aadhaar Card (if available)nMother and Child Protection (MCP) CardnPregnancy registration recordsnAny government-issued identity proof (if available)","benefit_type":"Service Delivery","benefit_description":"Free normal delivery and Caesarean section (C-section).nFree medicines and consumables.nFree diagnostic tests.nFree blood and blood products, if required.nFree diet during hospital stay.nFree transport from home to health facility.nFree inter-facility transfer (if referred).nFree drop-back transport from hospital to home.nFree treatment for sick newborns up to 30 days after birth.nFree treatment for sick infants up to 1 year of age at public health facilities","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Register pregnancy at the nearest Government health facility.nVisit a Government hospital/PHC/CHC for delivery or treatment.nInform hospital staff that you wish to avail JSSK benefits.nReceive eligible services free of cost","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":62,"scheme_code":"JK-SCH-0062","name":"Pradhan Mantri Surakshit Matritva Abhiyan (PMSMA)","short_name":"PMSMA","slug":"pradhan-mantri-surakshit-matritva-abhiyan-pmsma","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"All pregnant women.nSpecial focus on women in the 2nd and 3rd trimesters","eligibility_summary":"MCP (Mother and Child Protection) Card / ANC Card.nAadhaar Card or any identity proof (if available).nPrevious medical records and test reports (if any)","benefit_type":"In-kind / Material","benefit_description":"Free comprehensive antenatal check-upnExamination by doctors, including specialists where available.nBlood pressure, weight, and pregnancy assessment.nFree laboratory tests (blood and urine tests).nScreening for high-risk pregnancies.nCounseling on nutrition, birth preparedness, and danger signs.nReferral and follow-up care for high-risk pregnancies.nEarly detection and management of pregnancy complications","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Government health facilitynCarry your ANC/MCP card and relevant medical records.nRegister for PMSMA services.nReceive free antenatal check-up and counseling","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":63,"scheme_code":"JK-SCH-0063","name":"Rashtriya Bal Swasthya Karyakram (RBSK)","short_name":"RBSK","slug":"rashtriya-bal-swasthya-karyakram-rbsk","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Newborns (0–6 weeks)nChildren (6 weeks–6 years) attending Anganwadi CentresnSchool-going children (6–18 years) in Government and Government-aided schools","eligibility_summary":"Birth Certificate (if available)nAadhaar Card (if available)nSchool ID or Anganwadi registration detailsnHealth records/MCP Card (if available)","benefit_type":"Cash Benefit","benefit_description":"Free health screening for children from birth to 18 years.nEarly identification of health conditions under the 4 Ds:nDefects at BirthnDeficienciesnDiseasesnDevelopmental Delays & DisabilitiesnFree medical examinations and diagnostic services.nReferral to specialized healthcare facilities when required.nFree treatment and surgical interventions for identified conditions.nEarly intervention services for developmental delays and disabilities.nFollow-up care and monitoring","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Health screening is conducted at:nPublic health facilitiesnAnganwadi CentresnGovernment and Government-aided schoolsnMobile Health Teams conduct regular screenings.nChildren identified with health conditions are referred for further diagnosis and treatment.nEligible children receive free treatment and follow-up care","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":64,"scheme_code":"JK-SCH-0064","name":"Rashtriya Kishore Swasthya Karyakram (RKSK)","short_name":"RKSK","slug":"rashtriya-kishore-swasthya-karyakram-rksk","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Adolescents aged 10–19 years.nBoth boys and girls","eligibility_summary":"No specific documents are generally required for counseling and basic services.nAadhaar Card or school ID may be requested for certain services or referrals","benefit_type":"Training","benefit_description":"Free adolescent-friendly health services and counseling.nNutrition counseling and prevention of anemia.nMenstrual health and hygiene support.nSexual and reproductive health education and counseling.nMental health counseling and psychosocial support.nSubstance abuse prevention and counseling.nInformation on prevention of injuries and violence.nScreening and referral for health issues.nPeer education and life-skills education programmes.nAccess to Adolescent Friendly Health Clinics (AFHCs)","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Adolescent Friendly Health Clinic (AFHC), PHC, CHC, or District Hospital.nParticipate in school-based or community-based adolescent health programmes.nAccess counseling, health screening, and referral services free of cost","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":65,"scheme_code":"JK-SCH-0065","name":"National Programme for Prevention and Control of Non-Communicable Diseases (NP-NCD)","short_name":"NP-NCD","slug":"national-programme-for-prevention-and-control-of-non-communicable-diseases-np-ncd","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"All citizens, especially adults aged 30 years and above for population-based screening.nIndividuals at risk of or suffering from NCDs","eligibility_summary":"Aadhaar Card or any identity proof (if available).nABHA ID (if available).nPrevious medical records/reports (if any)","benefit_type":"Cash Benefit","benefit_description":"Free screening for diabetes, hypertension, and common cancers.nEarly detection and diagnosis of NCDs.nFree treatment and follow-up services at government health facilities.nRegular monitoring of blood pressure and blood sugar.nHealth counseling on diet, exercise, and lifestyle modification.nReferral services for specialized treatment when required.nCommunity-based screening for adults aged 30 years and above.nAwareness and prevention programmes for NCDs.nAccess to NCD clinics at District Hospitals and Community Health Centres","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Health & Wellness Centre (HWC), PHC, CHC, or District Hospital.nUndergo screening for NCDs.nReceive counseling, diagnosis, treatment, and follow-up services.nIf necessary, get referred to higher-level facilities for specialized care","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":66,"scheme_code":"JK-SCH-0066","name":"National Programme for Palliative Care (NPPC)","short_name":"NPPC","slug":"national-programme-for-palliative-care-nppc","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Patients suffering from:nnCancernAdvanced chronic diseasesnTerminal illnessesnSevere debilitating conditions requiring palliative care","eligibility_summary":"Aadhaar Card or any identity proof (if available)nMedical records/prescriptionsnReferral documents (if applicable)nABHA ID (if available)","benefit_type":"Service Delivery","benefit_description":"Free or affordable palliative care services.nPain relief and symptom management.nHome-based and community-based palliative care support.nCounseling and psychosocial support for patients and families.nEnd-of-life care services.nReferral to specialized palliative care centres.nSupport for patients with cancer, advanced chronic diseases, and terminal illnesses","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Government Hospital, District Hospital, Medical College, or Health & Wellness Centre.nConsult a doctor for assessment.nIf eligible, receive palliative care services or referral to a specialized palliative care unit.nFollow-up care and counseling are provided as required","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":67,"scheme_code":"JK-SCH-0067","name":"National TB Elimination Programme (NTEP)","short_name":"NTEP","slug":"national-tb-elimination-programme-ntep","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Any person diagnosed with Tuberculosis (TB).nPresumptive TB patients requiring testing and diagnosis.nDrug-sensitive and drug-resistant TB patients","eligibility_summary":"Aadhaar Card or any identity proof (preferred but not mandatory for treatment).nMedical records/test reports.nBank account details (for DBT benefits).nMobile number (if available)","benefit_type":"Cash Benefit","benefit_description":"Free TB screening and testing.nFree chest X-ray and diagnostic services (as per guidelines).nFree TB medicines for drug-sensitive and drug-resistant TB.nFree treatment and follow-up care.nNutritional support through Nikshay Poshan Yojana.nDirect Benefit Transfer (DBT) for eligible TB patients.nContact tracing and screening of family members.nCounseling and treatment adherence support.nFree treatment for multidrug-resistant (MDR) and extensively drug-resistant (XDR) TB.nCommunity-based TB care and support services","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Health & Wellness Centre, PHC, CHC, District Hospital, or Government-recognized TB centre.nUndergo TB screening and diagnostic testing.nIf diagnosed, enroll under NTEP through the Nikshay system.nReceive free medicines, treatment, nutritional support, and follow-up care","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[]},
  {"id":68,"scheme_code":"JK-SCH-0068","name":"National AIDS Control Programme (NACP)","short_name":"NACP","slug":"national-aids-control-programme-nacp","description":null,"scheme_level":"National","state_id":null,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Any individual seeking HIV counselling and testing.nPeople diagnosed with HIV who require free ART and related services.nPregnant women, key populations, and individuals at risk of HIV infection are also eligible for programme services","eligibility_summary":"Aadhaar Card or any valid government photo ID (if available)nAddress proof (if available)nMobile numbernHIV-positive test report (or confirmation through the government testing facility)nReferral slip (if referred from another health facility)","benefit_type":"Service Delivery","benefit_description":"HIV counselling and testing through Integrated Counselling and Testing Centres (ICTCs).nAntiretroviral Therapy (ART) for People Living with HIV (PLHIV) to suppress the virus and improve quality of life.nLaboratory investigations, including CD4 count and viral load testing, for monitoring treatment.nPrevention of Parent-to-Child Transmission (PPTCT) services for pregnant women living with HIV.nScreening and treatment of opportunistic infections and management of sexually transmitted infections (STIs).nAdherence counselling, psychosocial support, and follow-up care to ensure successful treatment.nFree condoms and HIV prevention services for key and vulnerable populations.nSafe blood transfusion services through strengthened blood banks.nLinkage to social welfare schemes and community support services through NACO and State AIDS Control Societies (SACS), wherever applicable","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Integrated Counselling and Testing Centre (ICTC), government hospital, or designated ART Centre.nRegister for confidential HIV counselling and testing.nIf diagnosed with HIV, you will be referred to an ART Centre for registration and clinical assessment.nSubmit the required identification and contact details (where applicable).nAfter enrolment, receive free antiretroviral medicines, regular follow-up, laboratory investigations, counselling, and adherence support under the programme","portal_url":null,"helpline_number":null,"source_url":"https://naco.gov.in/nacp","source_website":"naco.gov.in","is_active":true,"applicable_states":[]},
  {"id":69,"scheme_code":"JK-SCH-0069","name":"Rehabilitation Treatment for the Disabled","short_name":null,"slug":"rehabilitation-treatment-for-the-disabled","description":null,"scheme_level":"State","state_id":23,"theme_id":1,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Resident of Meghalaya.nPerson with a disability requiring rehabilitation or medical treatment.nUnable to afford the cost of treatment","eligibility_summary":"Disability Certificate.nAadhaar Card or any valid government-issued photo ID.nProof of residence in Meghalaya.nMedical records/prescription or treatment recommendation.nIncome certificate (if required).nBank account details.nPassport-size photographs","benefit_type":"Cash Benefit","benefit_description":"Financial assistance for medical treatment and rehabilitation.nSupport for treatment within Meghalaya or outside the state, where required.nAssistance to economically disadvantaged persons with disabilities who are unable to bear treatment co","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Obtain the application form from the District Social Welfare Officer (DSWO) or download it from the Meghalaya Government portal.nComplete the application form and attach the required documents.nSubmit the application to the District Social Welfare Officer of your district.nThe application is verified by the Social Welfare Department, and eligible beneficiaries receive financial assistance","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[23]},
  {"id":70,"scheme_code":"JK-SCH-0070","name":"Implementation of Disability Act – Book Grant, Uniform Grant & Unemployment Allowance for Persons with Disabilities","short_name":null,"slug":"implementation-of-disability-act-book-grant-uniform-grant-unemployment-allowance-for-persons-with-disabilities","description":null,"scheme_level":"State","state_id":23,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Meghalaya.nMust possess a valid Disability Certificate issued by the competent authority.nFor Book, Uniform, and Conveyance Grants: Applicant should be a student with a disability enrolled in a recognized educational institution.nFor Unemployment Allowance: Applicant should be an unemployed person with a disability and meet the conditions prescribed by the Social Welfare Department","eligibility_summary":"Duly filled application form.nDisability Certificate.nAadhaar Card or any valid government-issued photo ID.nProof of residence in Meghalaya.nRecent passport-size photographs.nBank account details/passbook.nFor student benefits: Bonafide certificate or admission certificate from the educational institution.nFor unemployment allowance: Employment Exchange Registration Certificate (where applicable) and any other documents prescribed by the department","benefit_type":"Cash Benefit","benefit_description":"Book Grant for students with disabilities to purchase books and study materials.nUniform Grant for eligible school-going students with disabilities.nConveyance Allowance to support transportation to educational institutions.nUnemployment Allowance for eligible unemployed persons with disabilities to provide financial support","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Obtain the prescribed application form from the District Social Welfare Officer (DSWO) or download it from the Meghalaya Social Welfare Department website.nComplete the application form and attach all required supporting documents.nSubmit the application to the District Social Welfare Officer of the concerned district.nAfter verification and approval by the Social Welfare Department, eligible beneficiaries receive the applicable grant or allowance","portal_url":null,"helpline_number":null,"source_url":"https://meghalaya.gov.in/index.php/schemes/content/15648","source_website":"meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":71,"scheme_code":"JK-SCH-0071","name":"Vocational Training to Persons with Disabilities (PwDs) for Self-Employment","short_name":null,"slug":"vocational-training-to-persons-with-disabilities-pwds-for-self-employment","description":null,"scheme_level":"State","state_id":23,"theme_id":9,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Meghalaya.nMust be a person with a disability possessing a valid Disability Certificate.nShould be willing to undergo vocational training for self-employment","eligibility_summary":"Duly filled application form.nDisability Certificate.nAadhaar Card or any valid government-issued photo ID.nProof of residence in Meghalaya.nRecent passport-size photographs.nBank account details (for stipend, if applicable)","benefit_type":"Scholarship / Fee Support","benefit_description":"Free vocational training in various trades for persons with disabilities.nStipend during the training period.nSkill development to support self-employment and sustainable livelihoods.nTraining delivered through recognized voluntary organizations in district headquarters","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the District Social Welfare Officer (DSWO) of your district.nComplete the application form and attach the required documents.nSubmit the application to the DSWO Office.nEligible applicants are enrolled in vocational training programmes conducted through approved voluntary organizations and receive the training stipend, where applicable","portal_url":null,"helpline_number":null,"source_url":"https://meghalaya.gov.in/index.php/schemes/content/15646","source_website":"meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":72,"scheme_code":"JK-SCH-0072","name":"Scholarship to Physically Disabled Students","short_name":null,"slug":"scholarship-to-physically-disabled-students","description":null,"scheme_level":"State","state_id":23,"theme_id":5,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Meghalaya.nMust be a student with a disability enrolled in a recognized school, college, or university.nMust possess a valid Disability Certificate/UDID Card.nThe scholarship is available for students pursuing education from pre-primary to postgraduate/university level","eligibility_summary":"Duly filled application form.nDisability Certificate or UDID Card.nAadhaar Card or any valid government-issued photo ID.nProof of residence in Meghalaya.nBonafide/Admission Certificate from the educational institution.nLatest mark sheet (for renewal, where applicable).nPassport-size photographs.nBank account details/passbook","benefit_type":"Scholarship / Fee Support","benefit_description":"Monthly scholarship for students with disabilities pursuing education from pre-primary to university level.nScholarship rates vary depending on the level of education and whether the student is a day scholar or hosteller.nReader's allowance is provided to visually impaired students from Class IX onwards.nState awards are also available for meritorious students with disabilities","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the Office of the District Social Welfare Officer (DSWO) in your district.nComplete the application form and attach all required documents.nSubmit the application to the DSWO Office.nAfter verification by the Social Welfare Department, eligible students receive the scholarship through the prescribed payment mechanism","portal_url":null,"helpline_number":null,"source_url":"https://meghalaya.gov.in/index.php/schemes/content/15645","source_website":"meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":73,"scheme_code":"JK-SCH-0073","name":"Training Centre for Self-Employment for Women","short_name":null,"slug":"training-centre-for-self-employment-for-women","description":null,"scheme_level":"State","state_id":23,"theme_id":9,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Women aged 15–45 years.nResidents of Meghalaya.nWomen in need of care and protection, including destitute women, widows, deserted women, single parents, orphan girls, and women from poor households.nSelection is made by a committee based on prescribed eligibility criteria","eligibility_summary":"Duly filled application form.nProof of age (Birth Certificate/School Certificate/Aadhaar).nAadhaar Card or any valid government-issued photo ID.nProof of residence in Meghalaya.nRecent passport-size photographs.nIncome certificate (if applicable).nDocuments supporting eligibility (e.g., widow/deserted certificate or recommendation from a recognized organization, where applicable)","benefit_type":"Scholarship / Fee Support","benefit_description":"Free vocational training in tailoring, knitting, embroidery, weaving, and other trades.nMonthly stipend during the training period.nPractical and theoretical skill development for self-employment and sustainable livelihoods.nOpportunity to become economically independent through income-generating activities","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the Office of the Superintendent, Training Centre for Self-Employment for Women in Need of Care and Protection.nComplete the application form and attach the required documents.nSubmit the application to the Superintendent of the Training Centre.nEligible applicants are selected by the Selection Committee and enrolled in the one-year vocational training programme","portal_url":null,"helpline_number":null,"source_url":"https://meghalaya.gov.in/index.php/schemes/content/15642","source_website":"meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":74,"scheme_code":"JK-SCH-0074","name":"Border Areas Scholarship","short_name":null,"slug":"border-areas-scholarship","description":null,"scheme_level":"State","state_id":23,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of a notified Indo–Bangladesh border village in Meghalaya.nMust belong to the Scheduled Caste (SC) or Scheduled Tribe (ST) category.nMust be pursuing a regular post-matric course in a recognized institution within or outside Meghalaya.nParent/guardian must be an Indian citizen, and the family's income should be derived from the border area.nApplicant should not be employed in any government or private establishment","eligibility_summary":"Duly filled application form (Fresh/Renewal).nProof of residence in a notified border village.nSC/ST Certificate.nPrevious examination mark sheet.nBonafide/Admission Certificate from the educational institution.nAadhaar Card or other valid photo ID.nPassport-size photographs.nBank account details/passbook.nAny other documents prescribed by the Directorate of Higher & Technical Education","benefit_type":"Scholarship / Fee Support","benefit_description":"Annual scholarship/stipend for eligible students pursuing post-matric education up to the degree level.nStudents can continue to receive this scholarship along with other eligible scholarship schemes, as it is treated as a grant/subsidy","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Online","application_process":"Obtain the Border Areas Scholarship application form from the Directorate of Higher & Technical Education or download it from the Meghalaya Government portal.nFill in the application form and attach all required documents.nSubmit the application through the Head of your Educational Institution.nThe institution forwards the application to the Directorate of Higher & Technical Education, Shillong, after the annual notification is issued","portal_url":null,"helpline_number":null,"source_url":"https://meghalaya.gov.in/index.php/schemes/content/37489","source_website":"meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":75,"scheme_code":"JK-SCH-0075","name":"Primary School Scholarship and Upper Primary Scholarship","short_name":null,"slug":"primary-school-scholarship-and-upper-primary-scholarship","description":null,"scheme_level":"State","state_id":23,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be studying in Class V (for the Primary Scholarship Examination) or Class VIII (for the Upper Primary Scholarship Examination) in a recognized school in Meghalaya.nStudents from eligible schools across the state may appear for the scholarship examination conducted by DERT.nSelection is based on merit in the scholarship examination","eligibility_summary":"Duly filled application form.nBonafide certificate from the school.nSchool enrolment/student identity details.nRecent passport-size photograph.nAadhaar Card or any other valid identity document (if required).nAny additional documents prescribed by DERT or the Sub-Divisional School Education Officer (SDSEO)","benefit_type":"Scholarship / Fee Support","benefit_description":"Financial scholarship awarded to meritorious students selected through a state-level scholarship examination.nScholarship is tenable for three years, subject to good conduct and satisfactory academic progress.nEncourages academic excellence and prepares students for future competitive examinations","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Apply through your school using the prescribed application form.nThe school forwards the applications to the Sub-Divisional School Education Officer (SDSEO).nDERT conducts the Primary and Upper Primary Scholarship Examination at designated examination centres across the state.nBased on merit, selected students are awarded scholarships by the Directorate of School Education and Literacy (DSEL)","portal_url":null,"helpline_number":null,"source_url":"https://meghalaya.gov.in/index.php/schemes/content/37593","source_website":"meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":76,"scheme_code":"JK-SCH-0076","name":"Chief Minister Housing Assistance Programme (CMHAP)","short_name":"CMHAP","slug":"chief-minister-housing-assistance-programme-cmhap","description":null,"scheme_level":"State","state_id":23,"theme_id":15,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a bona fide resident of Meghalaya.nMust be 18 years or older.nMust belong to:nEconomically Weaker Section (EWS): Annual family income up to ₹1,00,000; ornLow Income Group (LIG): Annual family income between ₹1,00,001 and ₹2,00,000.nMust not own a pucca house in Meghalaya (for LIG house construction assistance).nMust own land for construction (where applicable).nNeither the applicant nor spouse should have received housing assistance or a housing loan from the government under a similar scheme","eligibility_summary":"Prescribed application form.nAadhaar Card.nEPIC (Voter ID) or other valid proof of residence.nIncome Certificate.nLand ownership documents (for house construction).nBank account details/passbook.nRecent passport-size photographs.nDeclaration regarding ownership of house and previous housing assistance, if applicable","benefit_type":"Credit / Subsidy","benefit_description":"EWS households: Three bundles of 9-foot GCI roofing sheets as an outright grant to improve existing houses.nLIG households: Financial assistance of up to ₹75,000 under the Credit Linked Subsidy component for construction of a durable house (minimum carpet area of 19.20 sq. m. with at least two rooms).nHouses are constructed as per government-approved designs, with additional costs met through the beneficiary's own contribution, MGNREGS, SRWP, or bank loans, where applicable","benefit_amount":75000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the prescribed application form from the Block Development Officer (BDO), District Housing Officer (DHO), or Inspector of Housing.nFill in the application form and attach all required documents.nSubmit the completed application to the concerned BDO/DHO.nApplications are scrutinized by the Block/Urban Level Housing Selection and Monitoring Committee, and approved beneficiaries receive assistance as per the scheme guidelines","portal_url":null,"helpline_number":null,"source_url":"https://meghalaya.gov.in/index.php/schemes/content/37229","source_website":"meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":77,"scheme_code":"JK-SCH-0077","name":"Rural Housing Scheme (RHS)","short_name":"RHS","slug":"rural-housing-scheme-rhs","description":null,"scheme_level":"State","state_id":23,"theme_id":15,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Rural households in Meghalaya constructing their own houses with their own resources.nPriority was given to economically weaker and poor families in rural areas","eligibility_summary":"Prescribed application form.nProof of residence in Meghalaya.nIdentity proof (Aadhaar Card/EPIC or other valid government-issued ID).nIncome certificate, if required.nLand ownership or house construction details.nPassport-size photographs","benefit_type":"Cash Benefit","benefit_description":"Under the original RHS, eligible beneficiaries received three bundles of CGI (Corrugated Galvanized Iron) roofing sheets as a grant to complete the roofing of their houses.nThe scheme benefited over 71,000 rural households before being discontinued and replaced by CMHAP","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the Housing Department or the concerned district office.nComplete the application and attach the required documents.nSubmit the application to the concerned district housing authority for verification.nEligible applicants were provided roofing materials under the scheme. New applications are no longer accepted, as the scheme has been replaced by the Chief Minister's Housing Assistance Programme (CMHAP)","portal_url":null,"helpline_number":null,"source_url":"https://meghalaya.gov.in/index.php/schemes/content/37226","source_website":"meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":78,"scheme_code":"JK-SCH-0078","name":"FOCUS (Farmers' Collectivization for Upscaling Production and Marketing Systems)","short_name":null,"slug":"focus-farmers-collectivization-for-upscaling-production-and-marketing-systems","description":null,"scheme_level":"State","state_id":23,"theme_id":9,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident farmer of Meghalaya.nMust be a member of a registered Producer Group (PG).nShould be engaged in agriculture, horticulture, livestock, fisheries, or allied livelihood activities","eligibility_summary":"Aadhaar Card or other valid photo ID.nBank account details.nProof of residence.nProducer Group registration/membership details.nMobile number","benefit_type":"Cash Benefit","benefit_description":"One-time mobilization grant of ₹5,000 to each member of a registered Producer Group.nSupport for value chain development, aggregation, marketing, transportation, farm machinery, and livelihood enhancement.nCapacity building and technical support for Producer Groups","benefit_amount":5000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Join or form a Producer Group in your village.nRegister the group through the implementing agency/Block office.nSubmit the required documents and bank details.nAfter verification, eligible members receive the financial assistance through Direct Benefit Transfer (DBT)","portal_url":null,"helpline_number":null,"source_url":"https://mymeg.meghalaya.gov.in/","source_website":"mymeg.meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":79,"scheme_code":"JK-SCH-0079","name":"FOCUS+","short_name":null,"slug":"focus","description":null,"scheme_level":"State","state_id":23,"theme_id":9,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident producer household in Meghalaya.nAt least one family member should be registered with a Producer Group.nMust complete registration under the FOCUS+ programme","eligibility_summary":"Aadhaar Card.nBank account details/passbook.nProof of residence.nProducer Group registration details.nMobile number.nFOCUS+ registration form","benefit_type":"Cash Benefit","benefit_description":"₹5,000 cash assistance to each eligible producer household under FOCUS+.nBenefit is generally released in two instalments (₹1,000 upon registration and ₹4,000 after verification).nAdditional benefit over and above assistance received under the FOCUS scheme","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Offline","application_process":"Register through your Producer Group or designated Block office during the registration period.nSubmit the required documents and complete FOCUS+ enrolment.nAfter verification, a FOCUS+ card is issued to eligible beneficiaries.nFinancial assistance is transferred directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":"https://mymeg.meghalaya.gov.in/","source_website":"mymeg.meghalaya.gov.in","is_active":true,"applicable_states":[23]},
  {"id":80,"scheme_code":"JK-SCH-0080","name":"Megha Health Insurance Scheme (MHIS)","short_name":"MHIS","slug":"megha-health-insurance-scheme-mhis","description":null,"scheme_level":"State","state_id":23,"theme_id":1,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Meghalaya.nAll citizens of Meghalaya are eligible except State and Central Government employees covered under government reimbursement schemes.nBeneficiaries can check their eligibility on the MHIS portal or at designated enrolment centres","eligibility_summary":"Aadhaar Card (if available).nEPIC (Voter ID), MGNREGA Job Card, Birth Certificate, or any other government-issued photo ID.nProof of family relationship (such as Ration Card, Headman's Certificate, or other government records listing family members).nMobile number.nAdditional documents (e.g., Birth Certificate, Marriage Certificate, or Adoption Certificate) for adding new family members","benefit_type":"Insurance Cover","benefit_description":"Cashless hospitalization with health insurance coverage of up to ₹5.3 lakh per family per year on a floater basis.nCovers secondary and tertiary care, including surgeries, critical care, oncology, and several specialized treatments.nTreatment available at empanelled government and private hospitals within Meghalaya and at empanelled hospitals across India under the AB-PMJAY network.nCoverage for pre-existing diseases from the start of enrolment, subject to scheme guidelines","benefit_amount":530000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Check eligibility through the MHIS official portal or visit the nearest MHIS enrolment centre.nSubmit the required identity and family documents for enrolment.nAfter successful verification, receive the MHIS/AB-PMJAY card.nTo avail treatment, visit any empanelled hospital and present your MHIS/AB-PMJAY card along with a valid government-issued photo ID for cashless hospitalization","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[23]},
  {"id":81,"scheme_code":"JK-SCH-0081","name":"Chief Minister's Disability Pension Scheme","short_name":null,"slug":"chief-minister-s-disability-pension-scheme","description":null,"scheme_level":"State","state_id":23,"theme_id":1,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Meghalaya.nMust be 18–59 years of age.nMust possess a valid Disability Certificate issued by the competent authority.nApplicants receiving the Unemployment Allowance from the Social Welfare Department are not eligible under this scheme","eligibility_summary":"Duly filled application form.nDisability Certificate.nAadhaar Card or any valid government-issued photo ID.nProof of residence in Meghalaya.nPassport-size photographs.nBank account or Post Office account details.nAge proof (if required)","benefit_type":"Pension","benefit_description":"Monthly pension of ₹500 per eligible beneficiary.nPension is disbursed quarterly through the beneficiary's bank account or post office account.nBeneficiaries are issued a Pension Card for receiving pension payments","benefit_amount":500.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the District Social Welfare Officer (DSWO) or the Child Development Project Officer (CDPO) of the Social Welfare Department.nComplete the application form and attach all required documents.nSubmit the application to the DSWO/CDPO for verification.nUpon approval, a Pension Card is issued, and the pension is credited quarterly to the beneficiary's bank or post office account","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[23]},
  {"id":82,"scheme_code":"JK-SCH-0082","name":"CM ELEVATE","short_name":null,"slug":"cm-elevate","description":null,"scheme_level":"State","state_id":23,"theme_id":9,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Meghalaya.nIndividual applicants must be 18–58 years of age.nMust be eligible for a bank loan and not be a loan defaulter.nShould not have any pending criminal or legal case.nRegistered entities (societies, cooperatives, companies) and recognized groups such as SHGs, Village Organizations (VOs), and Producer Groups (PGs) are also eligible under applicable schemes.nGenerally, only one applicant per family is eligible under the programme","eligibility_summary":"Aadhaar Card, Voter ID, Passport, or Driving Licence (proof of identity and residence).nBank account details/passbook.nLand ownership/lease documents (where applicable).nNo Objection Certificate (NOC) from the village headman (where applicable).nCertificate from the Block Development Officer (BDO) or other competent authority, where required.nPAN Card, GST registration, Income Tax Returns, and bank statements (if applicable to the enterprise).nAny additional documents specified under the selected scheme","benefit_type":"Credit / Subsidy","benefit_description":"Financial assistance/subsidy ranging from 35% to 75% of the project cost, depending on the scheme.nAccess to bank credit and interest subvention under eligible schemes.nEntrepreneurship training, capacity building, mentoring, and handholding support.nAssistance for establishing or expanding businesses across multiple sectors","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official CM ELEVATE Portal.nRegister as an Individual, Registered Entity, or Group (SHG/VO/PG).nSelect the appropriate scheme based on your proposed enterprise.nComplete the online application and upload the required documents.nApplications are evaluated by the implementing department, financing bank, and evaluation committee.nUpon approval, eligible applicants receive financial assistance, loan support, and capacity-building services under the programme","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[23]},
  {"id":83,"scheme_code":"JK-SCH-0083","name":"Chief Minister's Social Assistance Scheme (CMSAS","short_name":null,"slug":"chief-minister-s-social-assistance-scheme-cmsas","description":null,"scheme_level":"State","state_id":23,"theme_id":23,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"For Single MothersnMust be a resident of Meghalaya.nMust be a single mother (widowed, divorced, abandoned, or unmarried with dependent children).nMust satisfy the eligibility criteria prescribed by the Social Welfare Department.nFor Infirm PersonsnMust be a resident of Meghalaya.nMust be medically certified as infirm and unable to earn a livelihood.nMust not be receiving similar benefits under another government pension scheme","eligibility_summary":"Duly filled application form.nAadhaar Card or proof of Aadhaar enrolment (Aadhaar authentication is required where applicable).nProof of residence.nBank account details/passbook.nRecent passport-size photographs.nCategory-specific documents:nDeath certificate/divorce decree/abandonment certificate (for single mothers, where applicable).nMedical certificate issued by a competent medical authority (for infirm persons)","benefit_type":"Pension","benefit_description":"Monthly financial assistance (pension) to eligible beneficiaries.nSupport is provided under categories such as:nPension for Single MothersnPension for Infirm PersonsnPension is credited directly to the beneficiary's bank account","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the Meghalaya State Public Services Delivery Commission (MSPSDC) online services portal or the nearest District Social Welfare Office (DSWO).nComplete the application form and upload or attach the required documents.nSubmit the application for verification by the Social Welfare Department.nUpon approval, the pension is sanctioned and transferred directly to the beneficiary's bank account","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[23]},
  {"id":84,"scheme_code":"JK-SCH-0084","name":"Pre-Matric Scholarship Scheme","short_name":null,"slug":"pre-matric-scholarship-scheme","description":null,"scheme_level":"State","state_id":34,"theme_id":5,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a domicile of Uttar Pradesh.nMust be studying in Class IX or X in a recognized school.nMust belong to an eligible category (SC, ST, OBC, General/EWS, or Minority) under the respective scholarship scheme.nMust satisfy the prescribed annual family income limit.nMust have an Aadhaar-linked bank account for DBT","eligibility_summary":"Aadhaar Card.nDomicile Certificate.nIncome Certificate.nCaste Certificate (where applicable).nPrevious year's mark sheet.nCurrent school admission/enrolment certificate.nAadhaar-linked bank account/passbook.nPassport-size photograph.nMobile number and email ID","benefit_type":"Scholarship / Fee Support","benefit_description":"Financial assistance for educational expenses, including maintenance allowance and other admissible school-related costs.nScholarship amount is transferred directly to the student's Aadhaar-linked bank account through Direct Benefit Transfer (DBT).nScholarship amount varies depending on the student's category and the applicable departmental scheme","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Uttar Pradesh Scholarship & Fee Reimbursement Portal (Saksham).nRegister as a Fresh or Renewal applicant.nFill in the online application form and upload the required documents.nSubmit the application online and print a copy.nSubmit the signed application along with supporting documents to your school for verification.nAfter verification by the institution and the concerned department, the scholarship amount is credited to the student's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":85,"scheme_code":"JK-SCH-0085","name":"Post-Matric Scholarship Scheme","short_name":null,"slug":"post-matric-scholarship-scheme","description":null,"scheme_level":"State","state_id":34,"theme_id":5,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a domicile of Uttar Pradesh.nMust be studying in Class XI or above (Intermediate, UG, PG, Diploma, ITI, Professional courses) in a recognized institution.nMust belong to an eligible category (SC, ST, OBC, General/EWS, or Minority).nAnnual family income should generally not exceed:n₹2,50,000 for SC/ST students.n₹2,00,000 for General, OBC, and Minority students.nMust have an Aadhaar-linked bank account","eligibility_summary":"Aadhaar Card.nDomicile Certificate.nIncome Certificate.nCaste Certificate (where applicable).nPrevious qualifying examination mark sheet.nAdmission/Bonafide Certificate from the institution.nFee receipt.nAadhaar-linked bank passbook.nPassport-size photograph.nMobile number and email ID","benefit_type":"Scholarship / Fee Support","benefit_description":"Scholarship for maintenance and educational expenses.nReimbursement of tuition and other admissible fees as per scheme guidelines.nDirect Benefit Transfer (DBT) of the scholarship amount to the student's Aadhaar-linked bank account.nAvailable for students belonging to SC, ST, OBC, General (EWS), and Minority categories under the respective departmental schemes","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Uttar Pradesh Scholarship & Fee Reimbursement Portal (Saksham).nRegister as a Fresh or Renewal applicant.nComplete the online application form and upload the required documents.nSubmit the application online and print the completed form.nSubmit the signed application and supporting documents to your educational institution for verification.nAfter verification by the institution and the concerned department, the scholarship amount is transferred directly to the student's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":86,"scheme_code":"JK-SCH-0086","name":"Old Age Pension Scheme (Vridhavastha Pension Yojana)","short_name":null,"slug":"old-age-pension-scheme-vridhavastha-pension-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":18,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Uttar Pradesh.nMust be 60 years of age or above.nAnnual family income should not exceed:n₹46,080 (Rural)n₹56,460 (Urban)nShould not be receiving benefits under any other government pension scheme","eligibility_summary":"Aadhaar Card.nAge proof (Birth Certificate, Aadhaar, Voter ID, etc.).nDomicile Certificate.nIncome Certificate.nAadhaar-linked bank account/passbook.nPassport-size photograph.nMobile number","benefit_type":"Pension","benefit_description":"₹1,000 per month as pension, credited directly to the beneficiary's Aadhaar-linked bank account through Direct Benefit Transfer (DBT).nPension is generally disbursed on a quarterly basis.nProvides financial support to elderly persons who have no regular source of income","benefit_amount":1000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Uttar Pradesh Integrated Social Pension Portal (SSPY).nSelect Old Age Pension (Vridhavastha Pension) and click on Apply Online.nComplete the online application form and upload the required documents.nSubmit the application and note the registration number for future reference.nThe application is verified by the concerned authorities, and upon approval, the pension is credited directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":"https://sspy.up.in/up-old-age-pension/","source_website":"sspy.up.in","is_active":true,"applicable_states":[34]},
  {"id":87,"scheme_code":"JK-SCH-0087","name":"National Family Benefit Scheme (Rashtriya Parivarik Labh Yojana)","short_name":null,"slug":"national-family-benefit-scheme-rashtriya-parivarik-labh-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":21,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Uttar Pradesh.nThe deceased must have been the primary/sole earning member of the family.nThe deceased should have been 18–59 years of age at the time of death.nThe family must belong to the Below Poverty Line (BPL) category.nAnnual family income should not exceed:n₹46,080 (Rural)n₹56,460 (Urban)nThe application must be submitted within one year from the date of death","eligibility_summary":"Aadhaar Card of the applicant.nDeath Certificate of the deceased earning member.nIncome Certificate.nResidence/Domicile Certificate.nBPL/Ration Card (where applicable).nAadhaar-linked bank account/passbook.nPassport-size photograph.nMobile number","benefit_type":"Cash Benefit","benefit_description":"One-time financial assistance of ₹30,000 to the eligible dependent family member.nThe amount is transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT).nDesigned to help families meet immediate financial needs after the loss of the main breadwinner","benefit_amount":30000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official National Family Benefit Scheme Portal of the Uttar Pradesh Government.nRegister as a new applicant and complete Aadhaar verification.nFill in the online application form and upload the required documents.nSubmit the application and note the registration number.nThe application is verified by the concerned authorities, and upon approval, ₹30,000 is transferred directly to the beneficiary's bank account through DBT. The state has digitized the process to improve transparency and aims to complete disbursal within 75 days of application","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":88,"scheme_code":"JK-SCH-0088","name":"Chief Minister's Mass Marriage Scheme (Mukhyamantri Samuhik Vivah Yojana)","short_name":null,"slug":"chief-minister-s-mass-marriage-scheme-mukhyamantri-samuhik-vivah-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":23,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Both the bride and groom must be permanent residents of Uttar Pradesh.nThe bride must be 18 years or older, and the groom must be 21 years or older on the date of marriage.nThe annual family income should be within the limit prescribed by the Government (currently up to ₹3 lakh under the revised guidelines).nThe scheme is open to all eligible economically weaker families, including SC, ST, OBC, General (EWS), Minority, widows, divorced, and abandoned women seeking marriage or remarriage","eligibility_summary":"Aadhaar Cards of the bride and groom.nProof of age (Birth Certificate, School Certificate, Aadhaar, or Voter ID).nDomicile/Residence Certificate.nIncome Certificate.nBank account details of the bride.nPassport-size photographs of both applicants.nCaste Certificate (where applicable).nWidow/Divorce certificate (if applicable)","benefit_type":"Cash Benefit","benefit_description":"Financial assistance of up to ₹1,00,000 per eligible couple (as per the latest revised provisions), which includes:n₹75,000 transferred directly to the bride's bank account.n₹10,000 for clothes, gifts, and essential household items.n₹15,000 towards the organization of the mass marriage ceremony.nMarriage ceremonies are conducted according to the customs and traditions of different religions and communities","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Both","application_process":"Visit the official Mukhyamantri Samuhik Vivah Yojana Portal.nComplete Aadhaar-based registration and fill in the online application form.nUpload the required documents and submit the application.nThe application is verified by the concerned district authorities.nUpon approval, the couple participates in a government-organized mass marriage ceremony, and the financial assistance is released as per the scheme guidelines","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":89,"scheme_code":"JK-SCH-0089","name":"Mukhyamantri Abhyuday Scheme","short_name":null,"slug":"mukhyamantri-abhyuday-scheme","description":null,"scheme_level":"State","state_id":34,"theme_id":5,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Uttar Pradesh.nShould be preparing for one of the eligible competitive examinations.nMust possess the minimum educational qualification required for the respective examination (e.g., Class XII for JEE/NEET, Graduation/Final Year for UPSC/UPPSC).nPreference is given to meritorious students from economically weaker sections","eligibility_summary":"Aadhaar Card.nDomicile Certificate.nEducational qualification certificates/mark sheets.nPassport-size photograph.nMobile number and email ID.nCaste Certificate (if applicable).nIncome Certificate (where applicable)","benefit_type":"Service Delivery","benefit_description":"Free online and offline coaching for competitive examinations such as UPSC, UPPSC, JEE, NEET, NDA, CDS, SSC, Banking, TET, and other government recruitment exams.nFree study materials, e-learning resources, previous years' question papers, mock tests, and doubt-clearing sessions.nGuidance and mentoring by IAS, IPS, IFS officers and subject experts.nMock interviews and career counselling for shortlisted candidates","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Abhyuday Portal: abhyuday.up.gov.in.nRegister as a new applicant using your basic details.nSelect the competitive examination for which coaching is required.nFill in the online application form and upload the required documents.nSubmit the application. Eligible candidates are enrolled for online coaching, while selection for offline coaching may be based on an online screening test, depending on the course","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":90,"scheme_code":"JK-SCH-0090","name":"Financial Assistance for Scheduled Castes / Scheduled Tribes Affected by Atrocities","short_name":null,"slug":"financial-assistance-for-scheduled-castes-scheduled-tribes-affected-by-atrocities","description":null,"scheme_level":"State","state_id":34,"theme_id":29,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must belong to the Scheduled Caste (SC) or Scheduled Tribe (ST) community.nMust be a victim (or dependent family member of a victim) of an offence registered under the SC/ST (Prevention of Atrocities) Act, 1989 or the Protection of Civil Rights Act, 1955.nAn FIR must be registered under the relevant provisions of the Act","eligibility_summary":"Duly filled application form (where applicable).nAadhaar Card or other valid identity proof.nCaste Certificate.nCopy of the FIR registered under the SC/ST (Prevention of Atrocities) Act.nMedical report/injury certificate (where applicable).nDeath certificate (in case of death of the victim).nBank account details/passbook.nPassport-size photograph.nAny other documents required by the District Social Welfare Department","benefit_type":"Cash Benefit","benefit_description":"Financial assistance ranging from ₹22,500 to ₹8,25,000, depending on the nature and severity of the offence, as prescribed under the SC/ST (Prevention of Atrocities) Rules.nRelief is provided in stages linked to the progress of the criminal case (e.g., after FIR, charge sheet, and trial).nAdditional support may include rehabilitation and other assistance as provided under the Act and Rules","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Offline","application_process":"Report the offence and register an FIR at the nearest police station under the SC/ST (Prevention of Atrocities) Act, 1989.nApproach the District Social Welfare Office or the designated authority for relief and rehabilitation.nSubmit the required documents, including the FIR, caste certificate, identity proof, and bank details.nAfter verification by the district authorities, financial assistance is sanctioned and transferred to the beneficiary's bank account in accordance with the prescribed stages of the scheme","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":91,"scheme_code":"JK-SCH-0091","name":"Grant Scheme for Marriage of Daughters of Scheduled Castes and General Category Poor Persons (Shaadi Anudan Yojana)","short_name":null,"slug":"grant-scheme-for-marriage-of-daughters-of-scheduled-castes-and-general-category-poor-persons-shaadi-anudan-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":23,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Uttar Pradesh.nThe applicant must belong to the Scheduled Caste (SC) or General Category from an economically weaker family.nThe bride must be at least 18 years of age and the groom at least 21 years of age.nAnnual family income should not exceed:n₹46,080 (Rural)n₹56,460 (Urban)nAssistance is available for up to two daughters in a family","eligibility_summary":"Aadhaar Card of the applicant and bride.nDomicile Certificate.nIncome Certificate.nCaste Certificate (for SC applicants).nProof of age of the bride and groom.nMarriage invitation card or Marriage Certificate (where applicable).nBank account details/passbook.nPassport-size photographs.nMobile number","benefit_type":"Cash Benefit","benefit_description":"One-time financial assistance of ₹20,000 per eligible daughter's marriage.nA maximum of two daughters per family are eligible for assistance.nThe assistance is intended to reduce the financial burden on poor families","benefit_amount":20000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Shaadi Anudan Portal.nRegister and complete the online application form.nUpload the required documents.nSubmit the application within the prescribed timeline.nAfter verification by the district authorities, the approved grant is released to the eligible beneficiary","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":92,"scheme_code":"JK-SCH-0092","name":"Mukhyamantri Kanya Sumangala Yojana (MKSY)","short_name":"MKSY","slug":"mukhyamantri-kanya-sumangala-yojana-mksy","description":null,"scheme_level":"State","state_id":34,"theme_id":5,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Uttar Pradesh.nThe girl child must be born on or after 1 April 2019.nAnnual family income should not exceed ₹3 lakh.nA maximum of two girl children per family are eligible (with certain exceptions, such as multiple births).nThe beneficiary must meet the educational or age-related criteria applicable to each stage of the scheme","eligibility_summary":"Aadhaar Card of the parents/guardian and the girl child (where available).nBirth Certificate of the girl child.nDomicile Certificate.nIncome Certificate.nBank account details.nPassport-size photograph.nImmunization certificate (for Stage II).nSchool/college admission certificate (for applicable stages)","benefit_type":"Cash Benefit","benefit_description":"Financial assistance of ₹25,000 per eligible girl, disbursed in six stages:nnStage I: ₹5,000 – At the birth of a girl child.nStage II: ₹2,000 – After completion of one year of age and full immunization.nStage III: ₹3,000 – On admission to Class I.nStage IV: ₹3,000 – On admission to Class VI.nStage V: ₹5,000 – On admission to Class IX.nStage VI: ₹7,000 – On admission to a degree, diploma, or certificate course after passing Class XII (or a two-year diploma)","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Both","application_process":"Visit the official Mukhyamantri Kanya Sumangala Portal: https://mksy.up.gov.in.nRegister using a mobile number and create a user account.nComplete the online application form for the relevant stage and upload the required documents.nSubmit the application online.nAfter verification by the concerned authorities, the financial assistance is transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT)","portal_url":"https://mksy.up.gov.in","helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":93,"scheme_code":"JK-SCH-0093","name":"Widow Pension Scheme (Nirashrit Mahila Pension Yojana)","short_name":null,"slug":"widow-pension-scheme-nirashrit-mahila-pension-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":25,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Uttar Pradesh.nMust be a widow or destitute woman aged 18 years or above.nMust have no regular source of income.nAnnual family income should not exceed:n₹46,080 (Rural)n₹56,460 (Urban)nShould not be receiving any other government pension","eligibility_summary":"Aadhaar Card.nHusband's Death Certificate.nDomicile/Residence Certificate.nIncome Certificate.nAadhaar-linked bank account/passbook.nPassport-size photograph.nMobile number.nAge proof (if required)","benefit_type":"Pension","benefit_description":"Monthly pension of ₹1,000, credited directly to the beneficiary's bank account through DBT.nFinancial support to help meet basic living expenses.nPension is subject to periodic verification and renewal as per government guidelines","benefit_amount":1000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Uttar Pradesh Social Pension Portal (SSPY).nSelect Nirashrit Mahila Pension and click Apply Online.nFill in the application form and upload the required documents.nSubmit the application and save the registration number for future reference.nAfter verification by the concerned authorities, the pension is sanctioned and transferred directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":94,"scheme_code":"JK-SCH-0094","name":"Divyang Pension Scheme (Viklang/Divyang Pension Yojana)","short_name":null,"slug":"divyang-pension-scheme-viklang-divyang-pension-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":23,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Uttar Pradesh.nMust be 18 years of age or above.nMust have at least 40% disability, certified by a competent government medical authority.nShould belong to an economically weaker household and satisfy the prescribed income criteria.nShould not be receiving another government disability pension","eligibility_summary":"Aadhaar Card.nDisability Certificate (40% or more) or UDID Card (if available).nDomicile/Residence Certificate.nIncome Certificate.nAadhaar-linked bank account/passbook.nPassport-size photograph.nMobile number.nAge proof (if required)","benefit_type":"Pension","benefit_description":"Monthly pension of ₹1,000 to eligible beneficiaries.nPension is transferred directly to the beneficiary's Aadhaar-linked bank account through Direct Benefit Transfer (DBT).nPension is generally disbursed on a quarterly basis","benefit_amount":1000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Uttar Pradesh Social Pension Portal (SSPY).nSelect Divyang Pension and complete the online application form.nUpload the required documents and submit the application.nThe application is verified by the concerned district authorities.nUpon approval, the pension is credited directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":95,"scheme_code":"JK-SCH-0095","name":"Mukhyamantri Bal Seva Yojana","short_name":null,"slug":"mukhyamantri-bal-seva-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":29,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Uttar Pradesh.nChild should generally be below 18 years of age (higher education support may continue up to 23 years for eligible students).nEligible categories include:nChildren who have lost one or both parents or a legal guardian.nChildren orphaned due to COVID-19 or other reasons (as per scheme provisions).nChildren rescued from child labour, child trafficking, child begging, or other exploitative situations.nChildren restored from Child Care Institutions or Observation Homes.nWhere one parent is alive, the prescribed annual family income limit must be met","eligibility_summary":"Duly filled application form.nAadhaar Card or valid identity proof.nBirth Certificate or age proof of the child.nDeath certificate(s) of parent(s)/legal guardian (where applicable).nResidence/Domicile Certificate.nIncome Certificate (where applicable).nSchool/College enrolment certificate.nBank account details/passbook.nPassport-size photographs.nAny additional documents as prescribed for the relevant category","benefit_type":"Training","benefit_description":"Monthly financial assistance of:n₹4,000 under the COVID category.n₹2,500 under the General category.nFree education up to Class XII and admission to residential schools for eligible children.nOne-time tablet/laptop for eligible students studying in Class IX and above or pursuing vocational education.nMarriage assistance of ₹1,01,000 for eligible girl beneficiaries (COVID category).nContinued financial support for eligible students pursuing higher education up to 23 years of age under prescribed conditions.nRehabilitation support for children rescued from child labour, child trafficking, child begging, and those restored from Child Care Institutions","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Both","application_process":"Visit the Mukhyamantri Bal Seva Yojana online portal or obtain the application form from the District Probation Office.nComplete the application form and attach the required documents.nSubmit the application online or through the Gram Panchayat/Block Office (rural areas) or Tehsil/District Probation Office (urban areas).nThe application is verified by the concerned authorities and approved by the District Level Committee.nUpon approval, benefits are transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT)","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":96,"scheme_code":"JK-SCH-0096","name":"Mukhyamantri Krishak Durghatna Kalyan Yojana","short_name":null,"slug":"mukhyamantri-krishak-durghatna-kalyan-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":23,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Uttar Pradesh.nMust be a farmer aged 18–70 years.nEligible beneficiaries include:nLand-owning farmers (Khatedar/Co-khatedar).nTenant farmers/sharecroppers (Bataidar).nLeaseholders and eligible farmer family members as per scheme guidelines.nThe accident must fall under the covered categories specified by the scheme","eligibility_summary":"Duly filled application form.nAadhaar Card.nResidence/Domicile Certificate.nLand records (Khatauni) or proof of tenancy/sharecropping, where applicable.nBank account details/passbook.nDeath Certificate (in case of death).nDisability Certificate or medical report (in case of disability).nFIR, post-mortem report, or Panchnama, where applicable.nPassport-size photograph","benefit_type":"Cash Benefit","benefit_description":"₹5 lakh in case of accidental death.n₹5 lakh for permanent total disability.n₹2.5 lakh for permanent partial disability (as prescribed under the scheme).nCovers accidents such as road accidents, drowning, lightning, snakebite, animal attacks, electrocution, fire, floods, and other notified accidental causes","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Offline","application_process":"Obtain the application form from the Tehsil Office or the office of the District Magistrate/Revenue Department.nComplete the application form and attach the required documents.nSubmit the application to the Tehsildar or the designated revenue authority within the prescribed time limit after the accident.nAfter verification by the district authorities, the approved financial assistance is transferred directly to the beneficiary's bank account","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":97,"scheme_code":"JK-SCH-0097","name":"Chief Minister Jan Arogya Abhiyan (Mukhyamantri Jan Arogya Abhiyan – MMJAA)","short_name":null,"slug":"chief-minister-jan-arogya-abhiyan-mukhyamantri-jan-arogya-abhiyan-mmjaa","description":null,"scheme_level":"State","state_id":34,"theme_id":1,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Uttar Pradesh.nFamily must be listed in the MMJAA beneficiary database maintained by SACHIS.nMust not already be covered under AB-PMJAY.nEligible families are identified by the Government based on notified criteria; there is no separate enrolment process","eligibility_summary":"Aadhaar Card.nAadhaar-linked mobile number.nRation Card.nFamily identification details as available in the MMJAA/SACHIS records.nAny additional identity document required for beneficiary verification","benefit_type":"Insurance Cover","benefit_description":"Cashless health insurance coverage of up to ₹5 lakh per family per year.nCovers secondary and tertiary hospitalization at empanelled government and private hospitals.nCovers pre-existing diseases from Day 1.nNo restriction on family size.nTreatment available across India through the PM-JAY empanelled hospital network with national portability","benefit_amount":500000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Check your eligibility through the Ayushman Bharat Beneficiary Portal or at a Common Service Centre (CSC) or an empanelled hospital.nIf your family is listed as eligible, generate your Ayushman Card using Aadhaar verification.nVisit any empanelled government or private hospital with your Ayushman Card and valid photo ID.nAfter verification, eligible beneficiaries can avail cashless treatment under the scheme","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":98,"scheme_code":"JK-SCH-0098","name":"Rani Lakshmibai Mahila Evam Bal Samman Kosh","short_name":null,"slug":"rani-lakshmibai-mahila-evam-bal-samman-kosh","description":null,"scheme_level":"State","state_id":34,"theme_id":29,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Women and girl children who are victims of heinous crimes, including rape, gang rape, acid attacks, offences under the POCSO Act, and other serious crimes.nDependent children of eligible victims may receive educational and medical assistance.nIn exceptional circumstances, women or girl children requiring urgent social and economic rehabilitation may also be considered under the scheme","eligibility_summary":"Duly filled application form (where applicable).nAadhaar Card or other valid identity proof.nCopy of the FIR.nMedical report/injury certificate.nBank account details/passbook.nPassport-size photograph.nDeath certificate (where applicable).nAny additional documents required by the District Probation Officer or District Level Committee","benefit_type":"Cash Benefit","benefit_description":"Financial assistance ranging from ₹1 lakh to ₹10 lakh, depending on the nature and severity of the offence.nFree medical treatment, including reconstructive surgery where required.nEducational and medical assistance for the minor children of victims, where applicable.nRehabilitation and other support services to help survivors recover and reintegrate into society","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Offline","application_process":"Report the incident to the police and ensure registration of an FIR.nApproach the District Probation Officer (DPO) or District Magistrate's Office for assistance under the scheme.nSubmit the required documents, including the FIR, identity proof, medical records, and bank account details.nThe District Level Steering Committee examines the case and recommends assistance.nUpon approval, financial assistance is transferred directly to the beneficiary's bank account, while medical and rehabilitation support is coordinated through the concerned departments","portal_url":null,"helpline_number":null,"source_url":"http://www.msk.upsdc.gov.in","source_website":"www.msk.upsdc.gov.in","is_active":true,"applicable_states":[34]},
  {"id":99,"scheme_code":"JK-SCH-0099","name":"Uttar Pradesh Building and Other Construction Workers (BOCW) Welfare Schemes","short_name":"BOCW","slug":"uttar-pradesh-building-and-other-construction-workers-bocw-welfare-schemes","description":null,"scheme_level":"State","state_id":34,"theme_id":32,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Uttar Pradesh.nMust be 18–60 years of age.nMust have worked in building or construction work for at least 90 days during the preceding 12 months.nMust be registered with the Uttar Pradesh Building and Other Construction Workers Welfare Board (UPBOCW).nRegistration must be renewed periodically to continue receiving benefits","eligibility_summary":"Aadhaar Card.nPassport-size photograph.nProof of age.nProof of residence.nBank account details/passbook.nProof of construction work (certificate from employer/contractor, work certificate, or self-declaration as prescribed).nMobile number.nAny additional documents required for specific welfare schemes","benefit_type":"Pension","benefit_description":"Financial assistance for children's education and scholarships.nMarriage assistance for workers and their daughters.nMaternity and paternity benefits.nAccident, disability, and death compensation.nPension after attaining the eligible age.nHousing assistance and toilet construction support.nMedical assistance and treatment.nToolkits, skill development, and vocational training.nAssistance for bicycles, safety equipment, and other welfare measures","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Register as a construction worker on the UPBOCW portal or through a Common Service Centre (CSC).nSubmit the required documents and proof of construction work.nAfter approval, obtain the Labour Card (Shramik Card).nLog in to the portal and apply online for the specific welfare scheme(s) for which you are eligible.nAfter verification by the Labour Department, eligible benefits are transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT)","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":100,"scheme_code":"JK-SCH-0100","name":"Mukhyamantri Yuva Swarozgar Yojana","short_name":null,"slug":"mukhyamantri-yuva-swarozgar-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":9,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Uttar Pradesh.nAge should be 18–40 years.nMust have passed at least High School (Class 10).nShould be unemployed and intending to establish a new enterprise.nShould not be a defaulter of any bank or financial institution.nShould not have availed benefits under similar self-employment schemes such as PMRY, PMEGP, or other State/Central Government self-employment schemes","eligibility_summary":"Aadhaar Card.nDomicile Certificate.nHigh School (Class 10) certificate/mark sheet.nPassport-size photograph.nBank account details.nProject Report/Business Plan.nCaste Certificate (if applicable).nDisability Certificate (if applicable).nAffidavit regarding eligibility.nMobile number and email ID","benefit_type":"Credit / Subsidy","benefit_description":"Bank loan up to ₹25 lakh for manufacturing/industrial projects.nBank loan up to ₹10 lakh for service sector enterprises.nMargin money subsidy:n15% of the project cost (General category).n25% of the project cost (SC/ST/OBC/Minorities/Women/Ex-servicemen/Persons with Disabilities), subject to prescribed limits.nSubsidy is released after successful establishment and operation of the enterprise as per scheme guidelines","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Both","application_process":"Visit the Directorate of Industries & Enterprise Promotion / Nivesh Mitra portal.nRegister as a new applicant.nComplete the online application form and upload the required documents.nSubmit the business project report and application.nThe application is scrutinized by the District Level Task Force Committee and forwarded to the financing bank.nUpon approval by the bank and the competent authority, the loan and eligible subsidy are sanctioned","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":101,"scheme_code":"JK-SCH-0101","name":"Mukhyamantri Nirashrit Besahara Govansh Sahbhagita Yojana","short_name":null,"slug":"mukhyamantri-nirashrit-besahara-govansh-sahbhagita-yojana","description":null,"scheme_level":"State","state_id":34,"theme_id":9,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Uttar Pradesh.nShould have adequate space and facilities to rear the adopted cattle.nFarmers, livestock rearers, Self-Help Groups (SHGs), and other eligible individuals are eligible to apply.nApplicants should be capable of properly caring for the adopted cattle","eligibility_summary":"Aadhaar Card.nResidence/Domicile Certificate.nBank account details/passbook.nPassport-size photograph.nMobile number.nAny additional documents required by the local Animal Husbandry Department or Gaushala authority","benefit_type":"Cash Benefit","benefit_description":"₹1,500 per month per adopted cow (₹50 per day) is provided through Direct Benefit Transfer (DBT).nFinancial assistance is available for adopting up to four destitute cows.nPromotes sustainable livestock rearing and provides an additional source of income through dairy products and organic manure","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Offline","application_process":"Visit the nearest Gaushala (Cow Shelter) or the District Animal Husbandry Office.nSubmit an application expressing willingness to adopt destitute cattle.nProvide the required documents for verification.nAfter verification of eligibility and cattle-rearing facilities, the cattle are allotted to the applicant.nUpon successful adoption, the monthly maintenance assistance is transferred directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[34]},
  {"id":102,"scheme_code":"JK-SCH-0102","name":"Rupashree Prakalpa","short_name":null,"slug":"rupashree-prakalpa","description":null,"scheme_level":"State","state_id":36,"theme_id":23,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of West Bengal (born in the state, resident for at least 5 years, or with parents who are permanent residents).nThe bride must be 18 years or older and unmarried at the time of application.nThe proposed marriage must be her first marriage.nThe prospective groom must be 21 years or older.nAnnual family income should not exceed ₹1.5 lakh.nThe applicant must have an active bank account in her own name","eligibility_summary":"Proof of age of the applicant (Birth Certificate, Aadhaar, Voter ID, etc.).nSelf-declaration of unmarried status.nIncome certificate/self-declaration certified by the competent authority.nProof of residence.nBank passbook (showing account details and IFSC code).nProof of proposed marriage (Marriage Invitation Card or Notice of Marriage Registration).nProof of age of the prospective groom.nPassport-size photographs of the bride and groom","benefit_type":"Cash Benefit","benefit_description":"One-time financial assistance of ₹25,000.nAmount is transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT).nEncourages marriage only after the legal age and supports women's social and economic security","benefit_amount":25000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Obtain the application form from the Block Development Office (BDO), Sub-Divisional Office (SDO), or Municipal Office, or apply through the official Rupashree Portal.nComplete the application form and attach the required documents.nSubmit the application 30–60 days before the proposed date of marriage.nThe application is verified through a field enquiry by the designated authority.nUpon approval, the ₹25,000 grant is transferred directly to the applicant's bank account, generally before the date of marriage","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":103,"scheme_code":"JK-SCH-0103","name":"Annapurna Bhandar Scheme","short_name":null,"slug":"annapurna-bhandar-scheme","description":null,"scheme_level":"State","state_id":36,"theme_id":23,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of West Bengal.nWomen aged 25–60 years.nShould satisfy the eligibility criteria notified by the State Government.nExisting eligible Lakshmir Bhandar beneficiaries continue under the scheme without submitting a fresh application, subject to verification","eligibility_summary":"Aadhaar Card.nAadhaar-linked bank account details.nProof of residence.nMobile number.nPassport-size photograph.nAny additional documents prescribed by the Government during verification","benefit_type":"Cash Benefit","benefit_description":"₹3,000 per month is provided to eligible women through Direct Benefit Transfer (DBT).nThe assistance can be used for food, healthcare, education, and other household needs.nExisting eligible beneficiaries of Lakshmir Bhandar are automatically migrated to the new scheme after verification","benefit_amount":3000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Annapurna Bhandar Portal or designated government facilitation centres.nRegister and complete the online application form (for new applicants).nUpload or submit the required documents.nAfter verification by the concerned authorities, eligible applicants receive the monthly assistance through DBT.nExisting eligible Lakshmir Bhandar beneficiaries are automatically migrated and generally do not need to submit a fresh application unless specifically notified","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":104,"scheme_code":"JK-SCH-0104","name":"Yuvasree Scheme (Yuvasree Prakalpa)","short_name":null,"slug":"yuvasree-scheme-yuvasree-prakalpa","description":null,"scheme_level":"State","state_id":36,"theme_id":9,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of West Bengal.nMust be 18–45 years of age.nMust be unemployed and registered as a job seeker in the Employment Bank.nMust have passed at least Class VIII.nShould not have received financial assistance or loans under any other State/Central Government self-employment scheme.nOnly one member per family is eligible","eligibility_summary":"Completed application form (Annexure I).nUnemployment Certificate (Annexure II) issued by a Group A Officer.nSelf-declaration (Annexure III).nAadhaar Card or other identity proof.nProof of age (Birth Certificate/Class X Admit Card/Certificate).nProof of residence.nEducational qualification certificates/mark sheets.nBank account details.nPassport-size photograph.nCaste Certificate (if applicable).nDisability Certificate (if applicable)","benefit_type":"Training","benefit_description":"Monthly unemployment assistance of ₹1,500 through Direct Benefit Transfer (DBT).nAccess to Employment Bank for job opportunities.nSkill development and vocational training to improve employability.nPlacement support for employment in government and private sectors","benefit_amount":1500.0,"benefit_amount_text":null,"application_mode":"Online","application_process":"Register as a Job Seeker on the Employment Bank, West Bengal portal.nObtain a valid Employment Bank registration number.nLog in and apply for the Yuvasree Scheme online.nUpload the required documents and submit the application.nAfter verification by the Labour Department, eligible beneficiaries are enrolled, and the monthly assistance is transferred directly to their bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":105,"scheme_code":"JK-SCH-0105","name":"Kanyashree Prakalpa","short_name":null,"slug":"kanyashree-prakalpa","description":null,"scheme_level":"State","state_id":36,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of West Bengal.nMust be unmarried.nK1: Girls aged 13–18 years enrolled in a recognized educational institution.nK2: Girls aged 18 years or above who are unmarried and continuing education or vocational training.nFamily annual income should generally not exceed ₹1.2 lakh. The income criterion is relaxed for girls with disabilities, orphan girls, and girls residing in Child Care Institutions","eligibility_summary":"Birth Certificate or other proof of age.nAadhaar Card (where applicable).nProof of residence.nIncome Certificate.nSchool/College enrolment certificate.nDeclaration of unmarried status.nBank account details in the applicant's name.nPassport-size photograph.nDisability certificate (if applicable)","benefit_type":"Scholarship / Fee Support","benefit_description":"K1: Annual scholarship of ₹1,000 for eligible unmarried girls aged 13–18 years enrolled in school or equivalent educational/vocational institutions.nK2: One-time grant of ₹25,000 to eligible unmarried girls after attaining 18 years of age, provided they are continuing education or vocational training.nK3: Higher education scholarship for girls pursuing undergraduate/postgraduate studies under notified institutions (amount as per prevailing government guidelines)","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Online","application_process":"Obtain the application form from the school, college, or educational institution where the applicant is enrolled, or apply through the official Kanyashree portal.nComplete the application form and attach the required documents.nSubmit the application to the Head of the Institution for verification.nThe institution forwards the verified application to the concerned authorities.nUpon approval, the scholarship/grant is credited directly to the beneficiary's bank account through Direct Benefit Transfer (DBT)","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":106,"scheme_code":"JK-SCH-0106","name":"Swasthya Sathi","short_name":null,"slug":"swasthya-sathi","description":null,"scheme_level":"State","state_id":36,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of West Bengal.nFamilies eligible under the State's enrolment criteria can avail benefits.nCertain categories already covered under specific government medical reimbursement schemes may not be eligible under the general enrolment process","eligibility_summary":"Aadhaar Card of family members.nProof of residence (such as Aadhaar, Ration Card, or other approved documents).nFamily identity documents (e.g., Ration Card/Khadya Sathi Card, if applicable).nPassport-size photograph.nMobile number.nAny additional documents required during enrolment or verification","benefit_type":"Insurance Cover","benefit_description":"Cashless health coverage up to ₹5 lakh per family per year.nCovers secondary and tertiary hospitalization, including surgeries, diagnostics, and specialized treatments.nNo premium is payable by beneficiaries; the entire premium is borne by the State Government.nCovers pre-existing diseases from the date of enrolment.nTreatment is available at empanelled government and private hospitals","benefit_amount":500000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Bangla Sahayata Kendra (BSK) or designated enrolment centre.nSubmit the required identity and family documents.nComplete biometric and document verification.nAfter successful verification, the Swasthya Sathi Smart Card is issued.nThe card can then be used to avail cashless treatment at empanelled hospitals across West Bengal","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":107,"scheme_code":"JK-SCH-0107","name":"Janma Mrityu Tathya Portal","short_name":null,"slug":"janma-mrityu-tathya-portal","description":null,"scheme_level":"State","state_id":36,"theme_id":1,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Applicable to all births and deaths occurring within West Bengal.nBirths and deaths should be registered under the Registration of Births and Deaths Act, 1969.nDelayed registration is permitted as per the prescribed legal procedure","eligibility_summary":"For Birth RegistrationnnBirth report from the hospital/institution or medical practitioner.nIdentity proof of parents.nProof of residence.nMobile number.nSupporting documents for delayed registration (if applicable).nnFor Death RegistrationnnMedical Certificate of Cause of Death (where applicable).nIdentity proof of the deceased/informant.nProof of residence.nCremation/Burial certificate (where applicable).nSupporting documents for delayed registration","benefit_type":"In-kind / Material","benefit_description":"Online registration of births and deaths.nDownload of digitally signed birth and death certificates.nFacility for certificate correction, delayed registration, status tracking, and certificate verification.nQR code-enabled certificates for easy authentication","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Janma Mrityu Tathya Portal.nRegister using your mobile number and OTP.nSelect the required service (Birth or Death Registration).nComplete the online application and upload the required documents.nTrack the application status online.nOnce approved, download the digitally signed certificate from the portal or obtain it from the concerned registration authority","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":108,"scheme_code":"JK-SCH-0108","name":"Swasthya Ingit Telemedicine","short_name":null,"slug":"swasthya-ingit-telemedicine","description":null,"scheme_level":"State","state_id":36,"theme_id":1,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of West Bengal.nPatients visiting government Health & Wellness Centres (Swasthya Kendras), Primary Health Centres (PHCs), or other participating government health facilities are eligible.nThe service is available based on referral and clinical assessment by the attending healthcare provider","eligibility_summary":"Aadhaar Card or another valid government-issued photo ID (if required).nHealth records, previous prescriptions, diagnostic reports, and investigation results (if available).nMobile number (where applicable for communication or follow-up)","benefit_type":"Service Delivery","benefit_description":"Free teleconsultation with specialist doctors at government health facilities.nAccess to specialist services in cardiology, neurology, oncology, paediatrics, obstetrics & gynaecology, psychiatry, nephrology, gastroenterology, tuberculosis, viral hepatitis, breast diseases, and other specialties.nReduces travel time and out-of-pocket medical expenses for rural patients.nFacilitates follow-up consultations, early diagnosis, timely referrals, and continuity of care. The programme has provided over 7 crore teleconsultations through more than 11,000 Health & Wellness Centres, supported by 63 specialist hubs and over 9,000 doctors","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Government Health & Wellness Centre (Swasthya Kendra), Primary Health Centre (PHC), or participating government health facility.nUndergo an initial examination by the attending Community Health Officer (CHO) or Medical Officer.nIf specialist consultation is required, the healthcare provider schedules a Swasthya Ingit teleconsultation.nConsult the specialist doctor through the telemedicine platform and receive prescriptions, advice, investigations, or referrals as needed.nReturn to the local health facility for follow-up care or further referral, if advised","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":109,"scheme_code":"JK-SCH-0109","name":"Sishu Saathi","short_name":null,"slug":"sishu-saathi","description":null,"scheme_level":"State","state_id":36,"theme_id":1,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of West Bengal.nChild should be 0–18 years of age.nMust be diagnosed with an eligible condition under the scheme through government screening or an empanelled hospital","eligibility_summary":"Aadhaar Card (if available).nProof of residence.nBirth Certificate or age proof of the child.nMedical records and diagnostic reports.nPassport-size photograph.nMobile number of the parent/guardian","benefit_type":"Service Delivery","benefit_description":"Free treatment and surgeries for eligible children at empanelled government and private hospitals.nCovers major conditions such as:nCongenital heart diseases (paediatric cardiac surgery)nNeurosurgical conditionsnCongenital cataract and other critical eye surgeriesnOther notified congenital disorders under the scheme.nCovers the entire cost of treatment, including hospitalization and surgery, with no out-of-pocket expenditure for the family","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest government health facility or empanelled hospital for screening, or participate in health screening conducted under RBSK in schools and Anganwadi centres.nIf the child is diagnosed with a covered condition, the case is referred to an empanelled treatment centre.nSubmit the required documents for verification.nUpon approval, the child receives cashless treatment and surgery at the designated hospital under the Sishu Saathi Scheme","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":110,"scheme_code":"JK-SCH-0110","name":"Swami Vivekananda Merit-cum-Means Scholarship (SVMCM)","short_name":"SVMCM","slug":"swami-vivekananda-merit-cum-means-scholarship-svmcm","description":null,"scheme_level":"State","state_id":36,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of West Bengal.nMust be enrolled in a recognized educational institution in West Bengal.nAnnual family income should not exceed ₹2.5 lakh.nMinimum qualifying marks:n60% in the last qualifying examination for Higher Secondary, Diploma, and Undergraduate courses.n53% in Honours at the undergraduate level for Postgraduate courses (General).n55% for Engineering/Technical Postgraduate courses.nApplicants should not be receiving any other government scholarship for the same course","eligibility_summary":"Aadhaar Card.nDomicile proof (Aadhaar Card/Voter ID/Ration Card/Domicile Certificate).nIncome Certificate.nLast qualifying examination mark sheet.nCurrent admission receipt/enrolment certificate.nBank passbook (first page showing account number and IFSC).nPassport-size photograph and signature.nInstitution declaration (if applicable, e.g., gap year)","benefit_type":"Scholarship / Fee Support","benefit_description":"Monthly scholarship ranging from ₹1,000 to ₹8,000, depending on the course and level of study.nFinancial assistance is provided through Direct Benefit Transfer (DBT) to the student's bank account.nAvailable for students pursuing Higher Secondary, UG, PG, Engineering, Medical, Polytechnic, Technical, Professional, and eligible Research courses","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Both","application_process":"Visit the official SVMCM Scholarship Portal.nRegister as a new applicant and complete the online application form.nUpload the required documents.nSubmit the application online and note the application ID for future reference.nThe application is verified by the educational institution and the concerned department.nUpon approval, the scholarship amount is credited directly to the student's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":111,"scheme_code":"JK-SCH-0111","name":"West Bengal Freeship Scheme (WBFS)","short_name":"WBFS","slug":"west-bengal-freeship-scheme-wbfs","description":null,"scheme_level":"State","state_id":36,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a domicile of West Bengal.nMust have secured admission to an eligible undergraduate Engineering, Technology, Pharmacy, or Architecture course in a self-financing private technical institution in West Bengal.nAdmission must be based on a State-level or National-level entrance examination.nAnnual family income must not exceed ₹2.5 lakh.nStudents already receiving benefits under the AICTE Tuition Fee Waiver (TFW) Scheme or the Swami Vivekananda Merit-cum-Means Scholarship (SVMCM) are not eligible under WBFS","eligibility_summary":"Aadhaar Card.nDomicile Certificate.nIncome Certificate.nEntrance examination rank card.nAdmission letter and fee receipt.nPassport-size photograph.nBank account details.nMobile number and email ID","benefit_type":null,"benefit_description":"Full or partial waiver of tuition fees, depending on eligibility and availability.nApplicable only to tuition fees; other fees (hostel, examination, library, etc.) must be borne by the student.nReduces the financial burden of pursuing professional technical education","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official West Bengal Freeship Scheme (WBFS) Portal.nRegister as a new applicant using your mobile number and email ID.nComplete the online application form and upload the required documents.nSubmit the application and note the Applicant ID for future reference.nThe institution verifies the application and forwards it to the Directorate for approval.nEligible students receive the approved tuition fee waiver as per the scheme guidelines","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":112,"scheme_code":"JK-SCH-0112","name":"Banglashree Scheme","short_name":null,"slug":"banglashree-scheme","description":null,"scheme_level":"State","state_id":36,"theme_id":9,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a Micro, Small, or Medium Manufacturing Enterprise located in West Bengal.nThe enterprise should meet the eligibility criteria prescribed under the Banglashree Scheme.nApplicable to new units, expansion, modernization, or diversification projects.nThe unit should possess valid Udyam Registration and other statutory registrations.nCertain industries included in the scheme's negative list are not eligible","eligibility_summary":"Udyam Registration Certificate.nPAN Card of the enterprise.nGST Registration Certificate.nProject Report.nLand/building ownership or lease documents.nTerm loan sanction letter (where applicable).nBank account details.nInvoices and proof of investment in plant and machinery.nAny additional documents prescribed by the MSME Department","benefit_type":"Credit / Subsidy","benefit_description":"State Capital Investment Subsidy for eligible new and expanding MSMEs.nInterest Subsidy on term loans for eligible enterprises.nReimbursement of Stamp Duty and Registration Fees.nNet SGST reimbursement for eligible manufacturing units.nPower subsidy and incentives for energy efficiency and environmental compliance.nAdditional incentives for women, SC/ST, and minority entrepreneurs in eligible categories","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Online","application_process":"Apply through the West Bengal MSME & Textiles Department or the SilpaSathi Single Window Portal.nRegister the enterprise and complete the online application for the relevant Banglashree incentive.nUpload the required documents and submit the application.nThe application is scrutinized by the concerned department.nUpon approval, eligible subsidies and incentives are released to the beneficiary as per the scheme guidelines","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":113,"scheme_code":"JK-SCH-0113","name":"Jai Johar Scheme","short_name":null,"slug":"jai-johar-scheme","description":null,"scheme_level":"State","state_id":36,"theme_id":18,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of West Bengal.nMust belong to the Scheduled Tribe (ST) community.nMust be 60 years of age or above.nShould not be receiving any other government social security pension or pension from any government organization","eligibility_summary":"Aadhaar Card.nScheduled Tribe (ST) Caste Certificate.nProof of residence/Domicile.nDigital Ration Card.nProof of age (Voter ID/Birth Certificate or other valid document).nBank account passbook.nPassport-size photograph.nMobile number","benefit_type":"Pension","benefit_description":"Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).nPension is credited directly to the beneficiary's bank account.nProvides financial support to elderly ST beneficiaries for meeting basic living expenses","benefit_amount":1000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the Block Development Office (BDO), Sub-Divisional Office (SDO), Municipality, Kolkata Municipal Corporation, or a Bangla Sahayata Kendra (BSK).nFill in the application form and attach the required documents.nSubmit the completed application to the designated office.nThe application is verified by the concerned authorities.nUpon approval, the ₹1,000 monthly pension is transferred directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":114,"scheme_code":"JK-SCH-0114","name":"Taposhili Bandhu Pension Scheme","short_name":null,"slug":"taposhili-bandhu-pension-scheme","description":null,"scheme_level":"State","state_id":36,"theme_id":18,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of West Bengal.nMust belong to the Scheduled Caste (SC) community.nMust be 60 years of age or above.nShould not be receiving any other government social security pension or pension from any government organization","eligibility_summary":"Aadhaar Card.nScheduled Caste (SC) Certificate.nProof of residence.nDigital Ration Card.nProof of age (Birth Certificate, Voter ID, or other valid document).nBank account passbook.nPassport-size photograph.nMobile number","benefit_type":"Pension","benefit_description":"Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).nPension is credited directly to the beneficiary's bank account.nProvides financial support for meeting basic living expenses","benefit_amount":1000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the Block Development Office (BDO), Sub-Divisional Office (SDO), Municipality, Kolkata Municipal Corporation, or a Bangla Sahayata Kendra (BSK).nFill in the application form and attach the required documents.nSubmit the completed application to the designated office.nThe application is verified by the concerned authorities.nUpon approval, the ₹1,000 monthly pension is transferred directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":115,"scheme_code":"JK-SCH-0115","name":"Manabik Pension Scheme","short_name":null,"slug":"manabik-pension-scheme","description":null,"scheme_level":"State","state_id":36,"theme_id":23,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of West Bengal.nMust have 40% or more disability, certified by a competent medical authority.nMust possess a valid Disability Certificate/UDID Card.nShould not be receiving another government disability pension or similar social security pension, as per scheme guidelines","eligibility_summary":"Aadhaar Card.nDisability Certificate/UDID Card.nProof of residence/Domicile.nDigital Ration Card (if applicable).nBank account passbook.nPassport-size photograph.nMobile number.nIncome Certificate (if required by the competent authority)","benefit_type":"Pension","benefit_description":"Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).nPension is credited directly to the beneficiary's bank account.nProvides regular financial support to meet basic living expenses and improve social security","benefit_amount":1000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the Block Development Office (BDO), Municipality, Sub-Divisional Office (SDO), or Duare Sarkar Camp.nComplete the application form and attach the required documents.nSubmit the application to the designated office for verification.nAfter approval by the competent authority, the pension is credited directly to the beneficiary's bank account through DBT.nPension is credited directly to the beneficiary's bank account.nProvides regular financial support to meet basic living expenses and improve social security","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":116,"scheme_code":"JK-SCH-0116","name":"Krishak Bandhu (Natun) Scheme","short_name":null,"slug":"krishak-bandhu-natun-scheme","description":null,"scheme_level":"State","state_id":36,"theme_id":23,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of West Bengal.nMust be a farmer with cultivable land recorded in official land records (RoR/Patta/Forest Patta) or an eligible registered sharecropper (Bhagchasi).nThe applicant must have a valid Aadhaar-linked bank account for DBT benefits","eligibility_summary":"Aadhaar Card.nRecord of Rights (RoR)/Patta/Forest Patta or registered sharecropper documents.nVoter ID or other identity proof.nBank passbook (first page).nPassport-size photograph.nMobile number","benefit_type":"Cash Benefit","benefit_description":"₹10,000 per year (paid in two equal instalments during the Kharif and Rabi seasons) for farmers with 1 acre or more of cultivable land.nFarmers with less than 1 acre of cultivable land receive pro-rata assistance, subject to a minimum of ₹4,000 per year.n₹2 lakh one-time death benefit to the nominee/legal heir if a registered farmer aged 18–60 years dies.nRegistered farmers may also receive preference under certain state agricultural support programmes","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Offline","application_process":"Obtain the application form from the Gram Panchayat Office, Block Agriculture Office, or the office of the Assistant Director of Agriculture.nFill out the application form and attach the required documents.nSubmit the completed application to the designated Agriculture Department office or Gram Panchayat.nThe application and land records are verified by the concerned authorities.nUpon approval, financial assistance and other benefits are transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT)","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":117,"scheme_code":"JK-SCH-0117","name":"Bangla Shasya Bima","short_name":null,"slug":"bangla-shasya-bima","description":null,"scheme_level":"State","state_id":36,"theme_id":21,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of West Bengal.nLoanee and non-loanee farmers cultivating notified crops are eligible.nIncludes owner cultivators, sharecroppers, and tenant farmers, subject to scheme guidelines.nLoanee farmers are covered as per the notified provisions","eligibility_summary":"Aadhaar Card.nVoter ID or other identity proof.nLand records/Record of Rights (RoR) or land possession certificate.nProof of cultivation (including tenancy/sharecropping documents, where applicable).nBank account details.nMobile number.nInsurance certificate/application details (for claims)","benefit_type":"Insurance Cover","benefit_description":"Free crop insurance with no premium payable by the farmer.nCompensation for crop loss due to:nPrevented/failed sowing.nMid-season adversity.nNatural calamities affecting standing crops.nPost-harvest losses for notified crops.nCoverage for both Kharif and Rabi notified crops","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the Gram Panchayat, Block Agriculture Office, or other designated Agriculture Department offices during the enrolment period.nComplete the application form and attach the required documents.nSubmit the application to the designated authority before the notified deadline for the relevant crop season.nAfter enrolment, farmers receive confirmation of insurance coverage.nIn case of crop loss, report the damage within the prescribed time to the Agriculture Department or the designated insurance agency to initiate the claim process","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":118,"scheme_code":"JK-SCH-0118","name":"State Social Security Scheme (Old Age, Widow & Disability Pension)","short_name":null,"slug":"state-social-security-scheme-old-age-widow-disability-pension","description":null,"scheme_level":"State","state_id":36,"theme_id":23,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of West Bengal.nMust belong to one of the following categories:nOld Age Pension: 60 years or above (55 years in certain disability-related cases).nWidow Pension: Widowed women with limited means of livelihood.nDisability Pension: Persons with 40% or more disability certified by a competent authority.nShould not be receiving another government social security pension for the same purpose","eligibility_summary":"Aadhaar Card.nProof of residence.nBank account/passbook.nPassport-size photograph.nAge proof (for old-age pension).nHusband's death certificate (for widow pension).nDisability Certificate/UDID Card (for disability pension).nIncome certificate (if applicable)","benefit_type":"Pension","benefit_description":"Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).nFinancial support for:nSenior citizens.nWidows.nPersons with disabilities.nPension is credited directly to the beneficiary's bank account","benefit_amount":1000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form from the Block Development Office (BDO), Municipality, Sub-Divisional Office (SDO), or Bangla Sahayata Kendra (BSK).nFill in the application form and attach the required documents.nSubmit the application to the designated authority.nThe application is verified by the concerned department.nUpon approval, the pension is credited directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":119,"scheme_code":"JK-SCH-0119","name":"Sabooj Sathi","short_name":null,"slug":"sabooj-sathi","description":null,"scheme_level":"State","state_id":36,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a student of Class IX, X, XI, or XII.nMust be enrolled in a government or government-aided school in West Bengal.nMust be a resident of West Bengal.nPreference is generally given to students in rural and economically weaker households","eligibility_summary":"School certificate or bonafide certificate from the institution.nAadhaar Card (if available).nProof of residence.nStudent identity card.nPassport-size photograph.nBank details (if required by the school/authority for verification purposes)","benefit_type":"In-kind / Material","benefit_description":"Free bicycle provided to eligible students studying in Class IX–XII.nHelps reduce travel time and transportation barriers to school.nPromotes school attendance, retention, and gender equality in education","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Online","application_process":"The school identifies eligible students based on enrolment in Classes IX–XII.nStudent details are submitted by the school to the education department through the official Sabooj Sathi portal.nDistrict authorities verify the list of beneficiaries.nBicycles are procured and distributed through schools or designated distribution camps.nStudents receive the bicycle free of cost from the government","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":120,"scheme_code":"JK-SCH-0120","name":"Karma Sathi Prakalpa","short_name":null,"slug":"karma-sathi-prakalpa","description":null,"scheme_level":"State","state_id":36,"theme_id":9,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of West Bengal.nAge should be 18–50 years.nMust have passed at least Class VIII.nShould be an intending entrepreneur proposing a new manufacturing, service, or trading venture.nOnly one member per family is eligible to apply.nPreference is given to applicants registered with the Employment Bank","eligibility_summary":"Aadhaar Card.nProof of residence.nEducational qualification certificate (minimum Class VIII).nPassport-size photograph.nProject report/business plan.nBank account details.nEmployment Bank registration (if applicable).nMobile number and email ID","benefit_type":"Credit / Subsidy","benefit_description":"Soft loan up to ₹2 lakh for establishing a new enterprise.nProject subsidy of 15% of the project cost, subject to a maximum of ₹25,000.nInterest subsidy:n50% of the interest for timely loan repayment (up to 3 years).n40% of the interest in other eligible cases (up to 3 years).nLoan is disbursed through the West Bengal State Cooperative Bank and affiliated cooperative banks","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Online","application_process":"Apply online through the Karma Sathi Prakalpa Portal or submit the prescribed application form to the District MSME Facilitation Centre (MFC).nFill in the application form and upload/attach the required documents.nSubmit the project report for evaluation.nThe application is scrutinized by the competent authority and forwarded to the financing cooperative bank.nUpon approval, the loan and eligible subsidies are sanctioned and disbursed as per the scheme guidelines","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":121,"scheme_code":"JK-SCH-0121","name":"Anandadhara (West Bengal State Rural Livelihoods Mission – WBSRLM)","short_name":null,"slug":"anandadhara-west-bengal-state-rural-livelihoods-mission-wbsrlm","description":null,"scheme_level":"State","state_id":36,"theme_id":9,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of rural West Bengal.nPrimarily intended for poor and vulnerable rural households, especially women.nApplicants should become members of an Anandadhara Self-Help Group (SHG).nEligibility is determined according to NRLM/WBSRLM guidelines","eligibility_summary":"Aadhaar Card.nProof of residence.nBank account details.nPassport-size photograph.nMobile number.nAny additional documents required for SHG membership or specific livelihood interventions","benefit_type":"Credit / Subsidy","benefit_description":"Formation and strengthening of Self-Help Groups (SHGs) and their federations.nAccess to bank credit, microfinance, and revolving funds.nSkill development and vocational training for livelihood enhancement.nSupport for micro-enterprises, agriculture, livestock, fisheries, and producer groups.nMarket linkage, value chain development, and entrepreneurship support for SHG members","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Contact the Gram Panchayat, Block Mission Management Unit (BMMU), or District Mission Management Unit (DMMU) under Anandadhara.nEnrol as a member of an existing Self-Help Group (SHG) or form a new SHG with eligible members.nComplete the registration process and submit the required documents.nParticipate in SHG meetings, capacity-building programmes, and livelihood planning.nEligible members can then access credit, training, livelihood support, and other benefits available under the Anandadhara/WBSRLM programme","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":122,"scheme_code":"JK-SCH-0122","name":"Khadya Sathi Scheme","short_name":null,"slug":"khadya-sathi-scheme","description":null,"scheme_level":"State","state_id":36,"theme_id":14,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of West Bengal.nMust possess or be eligible for a valid ration card under the Public Distribution System.nEligibility is determined based on the beneficiary category notified by the Department of Food & Supplies (such as Antyodaya Anna Yojana (AAY), Priority Household (PHH/SPHH), or Rajya Khadya Suraksha Yojana (RKSY))","eligibility_summary":"Aadhaar Card.nRation Card (or application for a new ration card).nProof of residence.nIdentity proof (e.g., Voter ID).nBirth certificate (for addition of children, where applicable).nPassport-size photograph","benefit_type":"Cash Benefit","benefit_description":"Rice and wheat at highly subsidized rates (generally ₹2 per kg for eligible beneficiaries under applicable categories).nFood grain entitlement varies according to the beneficiary's ration card category (e.g., AAY, PHH/SPHH, RKSY).nAccess through physical or digital (e-Ration) cards.nEnsures regular supply of essential food grains to eligible households","benefit_amount":2.0,"benefit_amount_text":null,"application_mode":"Online","application_process":"Apply for a new ration card or update an existing one through the Department of Food & Supplies, Government of West Bengal or the e-District/Online Ration Card Portal.nSubmit the prescribed application form along with the required documents.nThe application is verified by the concerned authorities.nUpon approval, a Khadya Sathi/Digital Ration Card is issued.nEligible beneficiaries can collect subsidized food grains every month from their designated Fair Price Shop (Ration Shop)","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[36]},
  {"id":123,"scheme_code":"JK-SCH-0123","name":"Savitribai Phule Kishori Samriddhi Yojana","short_name":null,"slug":"savitribai-phule-kishori-samriddhi-yojana","description":null,"scheme_level":"State","state_id":15,"theme_id":5,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Jharkhand.nMust be a girl enrolled in Classes VIII to XII in a recognized school.nShould meet the eligibility criteria prescribed by the Department, including continuation of education and compliance with the scheme conditions for the final installment.nThe applicant must have an Aadhaar-linked bank account","eligibility_summary":"Aadhaar Card.nResidence (Domicile) Certificate.nSchool admission/enrolment certificate.nRecent passport-size photograph.nBank account details/passbook.nMobile number.nBirth certificate or age proof.nAny other documents prescribed by the Department","benefit_type":"Cash Benefit","benefit_description":"Financial assistance is provided in stages:n₹2,500 for girls studying in Class VIII.n₹2,500 for girls studying in Class IX.n₹5,000 each for girls studying in Classes X, XI, and XII.nOne-time grant of ₹20,000 when the beneficiary attains 18 years of age and fulfills the scheme conditions.nThe total assistance under the scheme is up to ₹40,000, transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT)","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Both","application_process":"Apply through the Savitribai Phule Kishori Samriddhi Yojana Portal or through the concerned school/Block office.nFill in the application form and upload/submit the required documents.nThe application is verified by the school and the concerned district authorities.nUpon approval, the eligible financial assistance is credited directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":124,"scheme_code":"JK-SCH-0124","name":"Guruji Student Credit Card (GSCC) Scheme","short_name":"GSCC","slug":"guruji-student-credit-card-gscc-scheme","description":null,"scheme_level":"State","state_id":15,"theme_id":5,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a domicile of Jharkhand.nAge should not exceed 40 years.nMust have passed:nClass 10 from a recognized school in Jharkhand (for diploma courses), ornClasses 10 and 12 from recognized schools in Jharkhand (for undergraduate and higher courses).nMust have secured admission to an eligible recognized institution in India or abroad, as per the scheme guidelines (including specified institutions or those meeting prescribed NIRF/NAAC criteria).nShould not have previously availed benefits under the GSCC for the same course","eligibility_summary":"Aadhaar Card.nDomicile Certificate.nClass 10 and 12 mark sheets/certificates (as applicable).nAdmission letter and fee receipt.nCourse fee structure/prospectus.nPAN Card.nPassport-size photograph and signature.nCo-applicant's identity/address proof and photograph.nBank account details","benefit_type":"Credit / Subsidy","benefit_description":"Education loan up to ₹15 lakh without collateral.nSubsidized simple interest rate of 4% per annum.nNo processing fee.nRepayment period of up to 15 years, including a one-year moratorium after course completion or employment (whichever is earlier).nLoan covers tuition fees, hostel charges, books, laptops, and other approved education-related expenses","benefit_amount":1500000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the official Guruji Student Credit Card (GSCC) Portal and register as a new applicant.nComplete the online application form and upload the required documents.nSubmit the application for verification by the Department of Higher and Technical Education.nUpon approval, the application is forwarded to the designated bank for loan sanction.nAfter the loan is sanctioned, the amount is disbursed as per the approved education expenses","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":125,"scheme_code":"JK-SCH-0125","name":"Universal Pension Scheme (Sarvajan Pension Yojana)","short_name":null,"slug":"universal-pension-scheme-sarvajan-pension-yojana","description":null,"scheme_level":"State","state_id":15,"theme_id":23,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Jharkhand.nEligible categories include:nSenior citizens aged 60 years and above.nWidows aged 18 years and above.nPersons with at least 40% disability.nEligible single/abandoned women and persons living with HIV/AIDS.nThe applicant or an immediate family member should not be an income tax payer.nThe applicant or an immediate family member should not be a permanent employee of the Central/State Government or a Public Sector Undertaking (PSU)","eligibility_summary":"Aadhaar Card.nResidence (Domicile) Certificate.nBank account passbook.nPassport-size photograph.nProof of age (for old-age pension).nHusband's Death Certificate (for widow pension).nDisability Certificate (for disability pension).nMedical certificate from an ART Centre/Government Hospital (for HIV/AIDS pension).nMobile number","benefit_type":"Pension","benefit_description":"Monthly pension of ₹1,000 through Direct Benefit Transfer (DBT).nCovers the following categories:nOld Age Pension (60 years and above).nWidow Pension.nDisability Pension (40% or more disability).nSingle/abandoned women (as per scheme guidelines).nPension for persons living with HIV/AIDS.nPension is credited directly to the beneficiary's bank account every mon","benefit_amount":1000.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the Jharkhand Social Security Pension Portal or the nearest Block Development Office (BDO), Pragya Kendra/Common Service Centre (CSC), or District Social Security Office.nSelect the appropriate pension category and complete the application form.nUpload or submit the required documents.nThe application is verified by the concerned authorities.nUpon approval, the pension is transferred directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":126,"scheme_code":"JK-SCH-0126","name":"Mukhyamantri Maiya Samman Yojana","short_name":null,"slug":"mukhyamantri-maiya-samman-yojana","description":null,"scheme_level":"State","state_id":15,"theme_id":23,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Jharkhand.nMust be a woman aged 18–50 years.nAnnual family income should generally not exceed ₹8 lakh.nMust possess an Aadhaar-linked bank account.nThe applicant or her family should not include an income tax payer, a regular Central/State Government or PSU employee, or a recipient of certain government pensions, as per the scheme guidelines","eligibility_summary":"Aadhaar Card.nVoter ID.nRation Card.nResidence (Domicile) Certificate.nAadhaar-linked bank passbook.nPassport-size photograph.nMobile number.nSelf-declaration/undertaking as prescribed by the Government","benefit_type":"Cash Benefit","benefit_description":"₹2,500 per month (₹30,000 per year) transferred directly to the beneficiary's Aadhaar-linked bank account through DBT.nPromotes women's financial independence and supports household expenses.nNo contribution is required from the beneficiary","benefit_amount":null,"benefit_amount_text":"Multiple amounts specified (see benefit description)","application_mode":"Offline","application_process":"Obtain the application form from the Gram Panchayat, Block Office, Anganwadi Centre, Pragya Kendra (CSC), or designated enrolment camp.nFill in the application form and attach the required documents.nSubmit the application to the designated authority for verification.nAfter successful verification and approval, the financial assistance is credited directly to the beneficiary's Aadhaar-linked bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":127,"scheme_code":"JK-SCH-0127","name":"Abua Awas Yojana","short_name":null,"slug":"abua-awas-yojana","description":null,"scheme_level":"State","state_id":15,"theme_id":15,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Jharkhand.nMust be homeless or living in a kutcha house.nIncludes Particularly Vulnerable Tribal Groups (PVTGs), released bonded labourers, victims of natural calamities, and other eligible vulnerable households.nShould not have received benefits under PMAY-G, Birsa Awas Yojana, Indira Awas Yojana, or other notified government housing schemes.nFamilies owning a pucca house or meeting certain exclusion criteria (such as specified assets or government employment) are not eligible","eligibility_summary":"Aadhaar Card.nDomicile/Residence Certificate.nIncome Certificate.nBank account details/passbook.nMobile number.nLand ownership/possession documents (where applicable).nCaste Certificate (if applicable).nPassport-size photograph","benefit_type":"Cash Benefit","benefit_description":"Financial assistance of ₹2 lakh for construction of a pucca house.nHouse of approximately 31 sq. metres with three rooms, a kitchen, and a toilet.n95 days of MGNREGA wages for eligible beneficiaries to support house construction.nFinancial assistance is transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT)","benefit_amount":200000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Obtain the application form free of cost from the Gram Panchayat, Block Office, or designated government camps.nFill in the application form and attach the required documents.nSubmit the application to the designated authority.nThe Gram Sabha and concerned officials verify the applicant's eligibility.nUpon approval, financial assistance is released in instalments directly to the beneficiary's bank account as construction progresses","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":128,"scheme_code":"JK-SCH-0128","name":"Jharkhand State Food Security Scheme (JSFSS)","short_name":"JSFSS","slug":"jharkhand-state-food-security-scheme-jsfss","description":null,"scheme_level":"State","state_id":15,"theme_id":14,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Jharkhand.nMust belong to an economically vulnerable household as per state eligibility criteria.nMust possess or be eligible for a Green Card issued under the Jharkhand State Food Security Scheme (JSFSS).nHouseholds already covered under the National Food Security Act (NFSA) are generally not eligible under JSFSS","eligibility_summary":"Aadhaar Card.nResidence (Domicile) Certificate.nGreen Card (or documents required for Green Card issuance).nIncome Certificate (where applicable).nBank account details (if required).nPassport-size photograph","benefit_type":"Insurance Cover","benefit_description":"Subsidized or free rice for eligible Green Card holders.nMonthly distribution of food grains through the Public Distribution System (PDS).nEnsures food security for economically weaker and vulnerable households excluded from NFSA coverage","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest Fair Price Shop (PDS Dealer), Block Office, or Common Service Centre (CSC)/Pragya Kendra.nObtain and complete the Green Card/JSFSS application form.nSubmit the required documents for verification.nAfter approval, a Green Card is issued to the eligible household.nBeneficiaries can collect their monthly food grain entitlement from the designated Fair Price Shop","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":129,"scheme_code":"JK-SCH-0129","name":"Birsa Harit Gram Yojana (BHGY)","short_name":"BHGY","slug":"birsa-harit-gram-yojana-bhgy","description":null,"scheme_level":"State","state_id":15,"theme_id":9,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Jharkhand.nMust possess a valid MGNREGA Job Card.nPriority is given to:nScheduled Castes (SC) and Scheduled Tribes (ST).nSmall and marginal farmers.nLandless and Below Poverty Line (BPL) families.nWomen-headed households.nPersons with disabilities.nPMAY beneficiaries and other vulnerable rural households, as per scheme guidelines","eligibility_summary":"Aadhaar Card.nMGNREGA Job Card.nResidence (Domicile) Certificate.nCaste Certificate (if applicable).nLand ownership/possession certificate or landlessness certificate (as applicable).nBank account passbook.nPassport-size photograph","benefit_type":"In-kind / Material","benefit_description":"Plantation of fruit-bearing and fodder trees on eligible land.nUp to 100 days of wage employment under MGNREGA for plantation and maintenance activities.nUsufruct rights (right to use and benefit from the produce) for eligible beneficiaries.nPromotes long-term income generation through horticulture and agroforestry while improving environmental sustainability","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Contact the Gram Panchayat, Mukhiya, Village Head, MGNREGA Office, or Block Development Office (BDO).nSubmit the prescribed application along with the required documents.nBeneficiaries are identified and approved by the Gram Sabha.nAfter verification, plantation activities are undertaken under the MGNREGA framework.nEligible beneficiaries receive wage payments and long-term benefits from the plantation as per the scheme guidelines","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":130,"scheme_code":"JK-SCH-0130","name":"Mukhyamantri Pashudhan Vikas Yojana (MPVY)","short_name":"MPVY","slug":"mukhyamantri-pashudhan-vikas-yojana-mpvy","description":null,"scheme_level":"State","state_id":15,"theme_id":9,"service_approach_id":3,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Jharkhand.nMust be a farmer or livestock rearer.nPreference is given to SC/ST, economically weaker households, women, widows, persons with disabilities, and other vulnerable groups.nApplicant should have adequate land/shelter and basic facilities for rearing livestock.nLivestock training may be required for certain components of the scheme","eligibility_summary":"Aadhaar Card.nDomicile (Residence) Certificate.nRation Card.nCaste Certificate (if applicable).nLand ownership/possession documents.nBank account passbook.nPassport-size photograph.nMobile number.nLivestock training certificate (where applicable).nDisability/Widow certificate (if applicable)","benefit_type":"Training","benefit_description":"Subsidy for the purchase of milch cattle (cow/buffalo), goats, pigs, ducks, and poultry.nSubsidy up to 90% for eligible women, widows, persons with disabilities, and other notified vulnerable categories; up to 75% for other eligible beneficiaries (as per prevailing government norms).nSupport for animal care training and scientific livestock management.nPromotes self-employment and sustainable livelihood opportunities in rural areas","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Visit the nearest District Animal Husbandry Office, Block Animal Husbandry Office, or designated livestock development centre.nObtain and complete the prescribed application form.nAttach the required documents and submit the application.nThe application is verified by the concerned authorities, and beneficiaries are selected according to the scheme guidelines.nUpon approval, the subsidy and livestock assistance are provided through the implementing department","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":131,"scheme_code":"JK-SCH-0131","name":"Phoolo-Jhano Ashirwad Abhiyan","short_name":null,"slug":"phoolo-jhano-ashirwad-abhiyan","description":null,"scheme_level":"State","state_id":15,"theme_id":25,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Jharkhand.nWomen who are engaged in the production or sale of traditional liquor (Hadiya/Daru) and are willing to shift to an alternative livelihood.nPreference is given to women associated with or willing to join Self-Help Groups (SHGs)/Sakhi Mandals under JSLPS","eligibility_summary":"Aadhaar Card.nResidence (Domicile) Certificate.nBank account passbook (Aadhaar-linked).nPassport-size photograph.nMobile number.nSelf-Help Group (SHG) membership details (where applicable).nAny additional documents required by JSLPS or the District Administration","benefit_type":"Credit / Subsidy","benefit_description":"Interest-free loan of up to ₹10,000 to start an alternative livelihood or micro-enterprise.nCounselling, skill development, and handholding support for transitioning to sustainable occupations.nLinkage with Self-Help Groups (Sakhi Mandals) and JSLPS for financial inclusion and livelihood support.nAssistance in starting activities such as agriculture, animal husbandry, poultry, grocery shops, tailoring, forest produce enterprises, and other income-generating businesses","benefit_amount":10000.0,"benefit_amount_text":null,"application_mode":"Offline","application_process":"Contact the Gram Panchayat, Block Development Office (BDO), or the nearest JSLPS/SHG (Sakhi Mandal).nParticipate in the identification and counselling process conducted by JSLPS or district officials.nSubmit the prescribed application form with the required documents.nAfter verification, eligible women are linked with SHGs and provided skill training, counselling, and livelihood support.nUpon approval, the interest-free loan and livelihood assistance are provided to establish an alternative source of income","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":132,"scheme_code":"JK-SCH-0132","name":"Jharkhand Building and Other Construction Workers Welfare Schemes (JBOCWWB)","short_name":"JBOCWWB","slug":"jharkhand-building-and-other-construction-workers-welfare-schemes-jbocwwb","description":null,"scheme_level":"State","state_id":15,"theme_id":32,"service_approach_id":2,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a resident of Jharkhand.nMust be a building or construction worker aged 18–60 years.nMust have worked for at least 90 days in the preceding 12 months in building or construction work.nMust be registered with the Jharkhand Building and Other Construction Workers Welfare Board (JBOCWWB) and possess a valid Labour Card","eligibility_summary":"Aadhaar Card.nResidence (Domicile) Certificate.nAge proof.nPassport-size photograph.nBank account passbook.nEmployment/Construction Worker Certificate from employer/contractor or other prescribed proof.nLabour Card/JBOCWWB Registration Certificate.nAdditional documents as required for the specific welfare scheme (e.g., medical records, educational certificates, death certificate, etc.)","benefit_type":"Pension","benefit_description":"Financial assistance for education, maternity, marriage, and medical treatment.nAccident, disability, and death assistance for registered workers and their families.nTool kit assistance, bicycle assistance, pension, housing assistance, and other welfare benefits under various schemes.nSkill development and livelihood support for construction workers","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Register as a construction worker with the Jharkhand Building and Other Construction Workers Welfare Board (JBOCWWB) through the Labour Department portal, District Labour Office, or Common Service Centre (CSC).nObtain a valid Labour Card/Registration Certificate.nApply for the specific welfare scheme online or through the District Labour Office/CSC by submitting the prescribed application form and required documents.nThe application is verified by the concerned authorities.nUpon approval, eligible benefits are provided through Direct Benefit Transfer (DBT) or as specified under the respective welfare scheme","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":133,"scheme_code":"JK-SCH-0133","name":"Pre-Matric and Post-Matric Scholarship Schemes","short_name":null,"slug":"pre-matric-and-post-matric-scholarship-schemes","description":null,"scheme_level":"State","state_id":15,"theme_id":5,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Jharkhand.nMust belong to the SC, ST, BC, or Minority category.nPre-Matric: Students studying in Classes I–X in a recognized school.nPost-Matric: Students studying in Class XI or above in a recognized institution.nMust satisfy the income criteria prescribed by the Government for the respective scholarship category","eligibility_summary":"Aadhaar Card.nDomicile (Residence) Certificate.nCaste Certificate (where applicable).nIncome Certificate.nPrevious examination mark sheet.nBonafide/Admission Certificate from the institution.nBank account passbook (Aadhaar-linked).nPassport-size photograph.nMobile number","benefit_type":"Scholarship / Fee Support","benefit_description":"Financial assistance towards tuition fees, maintenance allowance, hostel fees, and other educational expenses.nPre-Matric Scholarship: For students studying from Class I to Class X.nPost-Matric Scholarship: For students pursuing Class XI onwards, including Intermediate, ITI, Diploma, Undergraduate, Postgraduate, Professional, and Technical courses.nScholarship amount is transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT)","benefit_amount":null,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the e-Kalyan Jharkhand Portal.nRegister as a new applicant and complete the online application form.nUpload the required documents.nSubmit the application for verification by the educational institution and district authorities.nUpon approval, the scholarship amount is credited directly to the beneficiary's bank account through DBT","portal_url":null,"helpline_number":null,"source_url":null,"source_website":null,"is_active":true,"applicable_states":[15]},
  {"id":134,"scheme_code":"JK-SCH-0134","name":"Mukhyamantri Sukhad Rahat Yojana (MSRY)","short_name":"MSRY","slug":"mukhyamantri-sukhad-rahat-yojana-msry","description":null,"scheme_level":"State","state_id":15,"theme_id":23,"service_approach_id":1,"priority_id":null,"feasibility_id":null,"scheme_status":"Active","active_enrollment":true,"launch_year":null,"target_group_summary":"Must be a permanent resident of Jharkhand.nMust be a farmer cultivating agricultural land in a drought-affected notified area.nBoth land-owning farmers and eligible sharecroppers/tenant farmers may apply, subject to government guidelines.nThe applicant should not be an income tax payer or fall under other exclusion criteria prescribed by the State GovernmentnResidents of Manipur belonging to eligible low-income households who are not covered under other government health insurance schemes","eligibility_summary":"Aadhaar Card.nResidence (Domicile) Certificate.nLand records or proof of cultivation (where applicable).nBank account passbook (Aadhaar-linked).nPassport-size photograph.nMobile number.nRation Card (if required for verification)nPermanent resident of Manipur belonging to an eligible low-income household and fulfilling the prescribed scheme criteria","benefit_type":"Insurance Cover","benefit_description":"One-time drought relief assistance of ₹3,500 to eligible farmer families affected by drought.nFinancial assistance is transferred directly to the beneficiary's bank account through Direct Benefit Transfer (DBT).nSupports farmers in meeting immediate livelihood and agricultural expenses after crop loss due to droughtnCashless health insurance coverage for secondary and tertiary medical treatment at empanelled hospitals, subject to scheme guidelines","benefit_amount":3500.0,"benefit_amount_text":null,"application_mode":"Both","application_process":"Visit the Mukhyamantri Sukhad Rahat Yojana Portal or the nearest Common Service Centre (CSC)/Pragya Kendra, Gram Panchayat, or Block Agri